INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (15, '你好，摩根。$B$B闪金镇的交易非常繁忙，所以我根本抽不出时间来帮你送货!$B$B我已委托帮我送这封信的人给你带去一包大蜡烛(你知道，可笑的狗头人总喜欢把这些东西戴在头上)。$B$B请向这位送货的人表示我们的感谢，并给予他合理的报酬。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (17, '刚到这里没几天，我就开始为附近农场中的孩子们上课了。我的课程进行得很顺利，镇长便委任我设立了一所学校，而且现在已经开始动工修建一所全新的校舍了!我从银松森林到暴风城，现在又来到月溪镇─谁能想到我会在艾泽拉斯经历那么多的事情!$B$B向您致意，$B$B斯塔文·密斯特曼托') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (19, '当冬天的雨季过后，道路适合旅行的时候，我会亲自前去找您。$B$B届时再见，$B$B银松的斯塔文·密斯特曼托') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (23, '...我从未想像我竟然会气成这样!她怎么敢这样对我!我教基尔斯数学的时候，蒂罗拉来了，还带着她的一个求婚者，他们竟公然手拉着手!真是个没教养的年轻人。蒂罗亚也没怎么介绍我，只是轻描淡写地说了句，「哦，这是我的家庭教师，斯塔文叔叔。他是个不错的老人家。」老人家!一听到这个词，我的脸就涨得通红。我不过比她大了几岁而已，而她竟背叛了...') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (25, '汤米·乔 :$B$B随着时间不断流逝，我的心因为没有你的存在而越发的失落。啊，只愿我们的家人能够超越他们之间愚蠢的仇恨，并且能认识到真正的罪恶其实就是这种仇恨。仇恨吞噬了我们的幸福，而且我担心受难的并非只有我们两个家族而已。$B$B如果他们能够明白这些，那么也许有一天我们可以走到一起。我希望能等到那一天，我将为此而活着。$B$B深爱你的梅贝尔') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (28, '阿格斯，$B$B正如你所知，我一直因为提供军队的补给需求而焦头烂额。我不应该对自己的工作有所抱怨，但是我们储备的铁即将用完。$B$B我已经没有足够的铁来制造马蹄铁了。我知道你有大量的储备，因此我想在下一批铁运到之前先向你借50双马蹄铁。$B$B对你表示万分感激，$B─弗纳') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (29, '木箱上附着一张纸条。上面写着:$B$B「弗纳─听说赤脊山遇到这样的麻烦，我感到甚是遗憾。这里是你所需要的马蹄铁。如果方便的话，请你尽快付给我100银币。」$B$B「如果你愿意的话，也可以用黑色幼龙的腹鳞来支付报酬(我听说黑色幼龙在赤脊山十分常见)。既然我们是朋友……4块鳞片就够了。谢谢你。─阿格斯」') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (30, '尊敬的大人，$B$B战争已经降临到我们的头上了。厄运正在一步步地向我们走来。$B$B作为湖畔镇的镇长，我有责任向您汇报最近在王国最东部地区所发生的军事活动。$B$B从我的信中，您可以了解到赤脊山地区和湖畔镇的现状。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (35, '北方的土地已经变成了邪恶力量的温床，我担心还会有更强大更黑暗的敌人接踵而来。暴风王国必须采取行动，以免让我们的城镇沦陷，人民沦为奴役。$B$B此致，$B$B所罗门镇长$B湖畔镇$B暴风王国') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (36, '尊敬的所罗门镇长:$B$B我和您一样为死去的人而哀悼。我会确保让国王陛下了解到目前的状况，同时我也衷心希望能为湖畔镇增派援军。不过奇怪的是，陛下最近没有什么举动，这件事我只能私下对您说说。$B$B请多加保重，$B$B马库斯·乔纳森将军$B暴风王国') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (39, '他们有一个庞大的地下网路。斯托曼，这个网路比你所知道的更为庞大。从藏宝海湾到暴风要塞都有他们的势力。也许你是个勇敢的圣骑士，不过如果你以为，凭你的一己之力就能阻止他们，那你就太傻了。他们正在研究一种大规模杀伤性武器。总之，那些石工的看家本领就是如何制造大家伙。你不会以为他们的兴趣只是南瓜田和葡萄园吧?我已经报答了你为我提供的帮助。现在，离我远点吧!$B$B─W') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (43, '我个人和艾德温·范克里夫相处了很久，根据我对他的了解，这么说吧，与他为敌不是那么容易的。要知道，他是我儿时的伙伴，是我亲自训练他的，因为我以为有一天他会和我并肩工作。如果范克里夫就是迪菲亚兄弟会的首脑，那么只能希望圣光怜悯我们的灵魂了。$B$B马迪亚斯·肖尔$B暴风城刺客公会') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (44, '我个人和艾德温·范克里夫相处了很久，根据我对他的了解，这么说吧，与他为敌不是那么容易的。要知道，他是我儿时的伙伴，是我亲自训练他的，因为我以为有一天他会和我并肩工作。如果范克里夫就是迪菲亚兄弟会的首脑，那么只能希望圣光怜悯我们的灵魂了。$B$B马迪亚斯·肖尔$B暴风城刺客公会') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (48, '黑爪:$B$B海洋在等待着我们，而我们需要你从北方运来的补给。尽力收集所有物资，一根铁轨一只水桶都不要放过，我们需要足够的金属。藏宝海湾那边本应有货物运来，但迟迟未到。黑爪，帮帮我，这次把你的补给直接运到「谷仓」去。我们不能再浪费时间了。$B$B- 范克里夫') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (49, '斯托曼大人:$B$B湖畔镇请求您的民兵的援助。在我写这封信的时候，我们正受到黑石氏族兽人，和莫甘斯率领的影皮豺狼人的夹击。如果形势不是如此严峻的话，我也不会向您求助。我们也在等待暴风城的援助，不过在他们的援军到来之前，我恳求您能对我们施以援手。暴风王国一旦腹背受敌，整个人类都将面临着危险。$B$B所罗门镇长') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50, '尊敬的阁下:$B$B西部荒野为您的失利而哀悼，但是我们这里也饱受战争的困扰，农夫都被盗贼和收割魔像赶走了，暴风城也撤走了他们的驻军，留下毫无防御的我们。在暴风城遗弃了我们之后，我召集组建了西部荒野人民军，试图夺回曾经属于我们的领土。如果我将人民军调往赤脊山的话，西部荒野必将遭受毁灭。$B$B我表示万分的遗憾和歉意。$B格里安·斯托曼') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (51, '埃伯洛克大人:$B$B湖畔镇请求守夜人的援助。我们正受到黑石氏族兽人和莫甘斯率领的影皮豺狼人的夹击。如果形势不是如此严峻的话，我也不会向您求助。我们也在等待暴风城的援助，不过在他们的援军到来之前，我恳求您能对我们施以援手。暴风王国一旦腹背受敌，整个人类都将面临着危险。$B$B所罗门镇长') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (52, '尊敬的阁下:$B$B我只能非常遗憾地告知您，守夜人部队现在不能离开夜色镇。也许您还没有注意到，暴风城已经不再为我们这个地区提供军事支援了。守夜人是完全由镇中的人民自发组建和训练的，他们的职责是在没有暴风城帮助的情况下保卫夜色镇。没有守夜人，夜色镇一定会沦陷。但愿您在困境中能有好运。$B$B- 艾尔罗·埃伯洛克领主') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (55, '这是一张西部荒野地产的契约。它赋予在契约上签名的拥有一块土地的所有权，以及该土地上面所有农作物和建筑物的所有权。$B$B在这份文件上签字的人是:$B$B    瑟多尔·法布隆$B    弗娜·法布隆') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (59, '当我们的同胞永远离去$B走进未知的土地$B在山谷的深处$B灵魂与精神变得坚强。$B当我们的同胞永远离去$B来到山上的圣殿$B我们将保卫他们永恒的精神$B将它镶入神圣的蓝水晶。$B当我们的同胞永远离去$B月亮照耀着山谷。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (63, '卡尔文大人:$B$B这位信差以证明自己信仰正义与圣光之道，并有能力与侵扰暮色森林的不死生物及恶魔战斗，$G他:她;也愿意加入卡尔文家族的伟大事业。$B$B我建议您给这位圣光的战士派遣更多工作─有些镇民可能在暗中帮助与圣光为敌的势力，不如让这位$C去调查一下。$B$B您忠诚的卡洛尔') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (64, '摩根·拉迪莫尔曾经是个伟大而高尚的骑士，他为了无辜、贫穷和饱受痛苦的人而战斗。多年来，他几乎跑遍艾泽拉斯所有的偏远地区，为受苦的人民带来安慰，惩戒那些作恶多端的人。$B$B在他十八岁那年的夏天，摩根与一位名叫莉丝的年轻女孩结婚了。他们彼此相爱，生了一个儿子和两个女儿。$B$B在摩根三十二岁那年，罗德隆的战争爆发了。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (70, '他的举动引起了三个守墓人的注意，他们试图阻止他。摩根在狂乱间转向他们，他把自己的愤怒和对罪恶的谴责，统统倾泻在这些无辜者的身上，他杀害了他们。$B$B杀人之后，摩根的愤怒逐渐散去，他的脑子也恢复了理智。在看到自己的剑，血淋淋地插在一个侍者的胸膛里，激烈的自责情绪，将他推向崩溃的边缘，他抽出匕首，猛然刺入自己的心脏。$B$B第二天，有人发现了摩根·拉迪莫尔，和另外三个无辜者的尸体。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (79, '以下是在艾尔文森林的矿坑中开采金矿的日程表。$B$B征收日程:$B$B周日:中午12:30$B周三:中午12:30$B$B在指定的日子里，从艾尔文森林的矿坑中开采出来的金矿将被集中在布莱克威尔南瓜田中。负责收取这些货物的「收货人」会佩戴一枚我交给他的特殊戒指。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (80, '格瑞林:$B$B我的时间很紧张，很多事情堆积在一起，让我抽不出身来，希望你对巨魔的调查不会让我更加繁忙。我授权你对付巨魔，你可以使用任何你认为必要的手段─只要你能找出一个有利的解决方案来。$B$B麦格尼·铜须') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (83, '第六天$B$B又是寒冷的一天。有雪，有巨魔，没有麦芽酒。$B$B第七天$B$B地上的雪很白，$B$B天很蓝，$B$B狼群又会在夜晚嚎叫，$B$B一滴酒也没有。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (84, '第八天$B$B巨魔的麻烦可能不像我们之前所想的那么严重。他们虽然数量众多，不过没有很好的装备和组织。只要组织小股力量就足以解决他们带来的威胁。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (87, '寒脊山谷和我们的雇佣兵(由参议院拨给我的行动基金来支付必需的费用)，我相信我们在短时间内就能解决这个问题。$B$B铜须陛下已经授权由我来指挥这次行动。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (89, '我认为，只要我们不要去侵犯他们的领地，巨魔对我们就不会构成实际的威胁。一般的矮人平民对这种情形可能并不感兴趣，不过考虑到军事资源的分散，为了谨慎行事，我们应将巨魔的问题置于次要的考虑，对我们来说，主要的威胁，仍然来自穴居怪和黑铁矮人。$B$B这里还一并附上了，我兄弟格瑞林关于安威玛情况报告的副本。$B$B森内尔·白须') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (91, '寒脊山谷和我们的雇佣兵(由参议院拨给我的行动基金来支付必需的费用)，我相信我们在短时间内就能解决这个问题。$B$B铜须陛下已经授权由我来指挥这次行动。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (94, '我们在一处隐蔽的洞穴避难，这里目前似乎挺安全。不过在有军队控制住迅猛龙之前，我们还是只能被困在这里。维尔加还在想办法继续工作，但我知道他可能还心有余悸。塔雷尔，这就是我们的处境。请布莱德·长须立刻派一只军队来营救我们。$B$B即使在这艰难的时刻，我也希望你一切都好。$B$B- 麦琳') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (112, '他的枪重重地击在他的肩膀上，枪管歪向一边，正好落在艾耶克的枪下面。艾耶克瞄准树冠适时地扣动了扳机，一声清晰的枪响过后，树冠上的一群鸟尖叫着四处飞散，树上冒出了一阵烟，我们惊异地看到一根巨大的树枝掉落下来，正好砸中了疾驰的黑豹。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (118, '我们匆忙射出的子弹为巴尼尔赢得了足够的逃跑时间。他大声叫嚷着跑下山丘，重新回到队伍之中。我们急忙离开了丛林，因为有一群凶残的鞭尾迅猛龙正在追寻着我们的足迹。$B$B现在攻守易位，猎手变成了猎物。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (119, '我带着队伍继续往海边走去，希望在那里的海岸线旁找到某个可以避开迅猛龙的地方。但是在匆忙之中，我们跑到了一处危险的高地，这是个可怕的错误，全都是我的错。我们停在了一个陡峭的悬崖边，而那些迅猛龙距离我们仅有几步之遥。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (121, '艾耶克和艾尔加丁爵士拿起他们的武器，守在我的两侧，我们的背后就是大海。巴尼尔沮丧地叹了一口长气，然后拿起了他的斧头。迅猛龙在慢慢地逼近，它们高傲地注视着我们，因为它们知道我们已经无路可逃了。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (124, '《荆棘谷的青山》$b$b 作者：赫米特·奈辛瓦里') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (163, '在遍布岩石的悬崖上，一只迄今为止我见过的最巨大的猎豹在晚霞的映衬中冒了出来。我笨拙地开了枪，但是那只豹丝毫未动。它又咆哮了一声，比第一次的声音更大，然后就消失了。$B$B我们把东西收好，然后神色黯然地返回了营地。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (174, '这头野兽压根没有发现我们的存在，事实上，它从我们这儿收到的第一个问候就是射入它双眼间的子弹。$B$B艾尔加丁爵士大声欢呼，艾耶克则赞许地向我点了点头。我从包里拿出烟斗，想好好庆祝一番。巴尼尔奔上山坡去拖迅猛龙的尸体。我看着被击倒的野兽，心里就像以前每一次杀死猎物时那样充满着兴奋和满足。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (175, '但是我还没有时间体会这次猎杀的愉悦，就赫然发现山顶上出现了几个影子─就在可怜的巴尼尔的正上方。$B$B「快跑，巴尼尔!」我大叫道。艾耶克、艾尔加丁和我立刻向追逐巴尼尔的迅猛龙射击，一时间子弹和箭矢乱飞，混乱之中，我们当中的某人还射杀了一只迅猛龙。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (176, '我们匆忙射出的子弹为巴尼尔赢得了足够的逃跑时间。他大声叫嚷着跑下山丘，重新回到队伍之中。我们急忙离开了丛林，因为有一群凶残的鞭尾迅猛龙正在追寻着我们的足迹。$B$B现在攻守易位，猎手变成了猎物。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (184, '最后，我必须再次强调我对炸药粉的迫切需求。我这里的存货已经非常少了，这会严重地阻碍挖掘行动的进展。我听说新的炸药粉补给会很快送来，但是我一直都没有收到。$B$B能否告诉我到底是什么原因导致这批货还没有运达我这里?$B$B此致，$B勘察员基恩萨·铁环') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (187, '如果我早知道会发生这样的事，我当初就算把自己的手砍了也决不会去抓那块雕着符文的木柄。我真是追悔莫及啊!后悔，我一直以为这是老人的特权，但现在我明白了，其实让人被后悔所缠绕的不是年岁，而是绝望，它让你再也无法摆脱后悔，只能饱受痛苦的煎熬。$B$B不过我已经像个诗人般喋喋不休好半天了。现在，我得继续我的日记……') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (188, '自从拔出那把镰刀之后，矿坑里就开始发生变化。火炬的光焰总是向一边倾斜，而我们对自己的声音也失去了控制。有时一个人的细声低语会突然变成吼叫声，传遍整个隧道，让人不得不掩住耳朵;而有时即使我们放声大喊，那声音却传不了多远就变得极其微弱，直至消失在风中。$B$B这让我们十分紧张，不过我们很快就不再担心这件事情了。因为有另一种力量将我们从矿坑里赶了出去─那就是狼人。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (189, '狼人从四面八方向我们袭来，从洞里冒出来抓向我们，或是从树上跳下来扑向我们。我们中的半数人在惊恐中被瞬间干掉，剩下的人都开始没命地逃跑。我看到自己的兄弟一个个丧身在狼人的尖牙或利爪之下，惨叫声不断划破寂静的森林。$B$B据我所知，我是唯一一个逃出那个地方的人。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (191, '也许我命中注定应该活下来亲眼看着我给暮色森林带来的巨变，亲眼看着狼人撕裂这片土地，以邪恶将这里玷污。$B$B如果这就是我的命运，那我的命运远不止这么糟糕。将魔爪伸向暮色森林的不仅仅是狼人─还有来自逆风小径的恶魔。$B$B我的下一章日记就要记述这些，我希望那也是最后一章……') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (192, '从罗兰之墓侥幸逃出来后，我躲在一个斯温家的谷仓里。我在那里面过了好几个星期，一直都被恐惧所笼罩，也不敢让斯温和他的家人知道我的存在。虽然从我对他们的观察来看，这些农夫都是些很本分的平民，而且如果我从藏身的地方走出去，他们也一定会接纳我住在他们家里，不过对我而言，要信任别人是十分困难的─尤其是经历了矿坑里那恐怖的一幕之后。$B$B因此我躲在那儿，一直没有现身。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (197, '我一直以来都不知道她的名字，因为她的丈夫和孩子总是叫她「亲爱的」，「宝贝」和「妈妈」。但是我很希望知道她的名字，我是唯一一个见证她当时的英勇行为的人。虽然她只是一个农夫的妻子，但是我从来没看到过有人能像她这么勇敢。$B$B她当然不知道那把镰刀是什么东西，但是当她知道黑骑士在寻找镰刀时，就突然想到了一个计画。$B$B那是个大胆而聪明的计画，如果她能成功的话，那该有多好!') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (198, '「镰刀?」她平静地问道。「我当然知道。这儿谁不知道?」她的双眼坚定地望着骑士，如果不是因为我知道实情的话，我一定也会相信她所说的话─虽然她根本不知道关于镰刀的事情。$B$B她的这一招奏效了。那个提出问题的骑士轻微地低下头凑向她，然后尖声说道:「在哪里?」$B$B「我可以带你去，带你们一起去。」她回答道。我看到她的眼中闪过一丝希望。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (199, '「不过路很远，带着孩子会拖累我们，必须得把他们留下。」$B$B她的计画很简单，不过简单的计画成功的可能性最大。如果她成功了，就能让那些强盗远离农场。她可能会因此而死，可是孩子们就安全了。如果强盗相信了她那崇高的谎言，这个计画就能成功。$B$B虽然我从未信仰过圣光之道，但是当斯温的妻子勇敢地站在那帮可怕的强盗面前时，我仍然虔诚地为她祈祷。$B$B「让他们相信吧。」我祈祷着。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (200, '他们站在那儿一动不动，而她也平静地面对着他们的凝视。这时一个骑士抬起眼，仿佛在聆听远方的召唤。他从衣服里拿出一块宝石，向它望去。他用宝石在斯温妻子的面前晃动。一股光芒从骑士的身上缓缓冒出，随即变成了一只恐怖的白色的手，伸向那个女人。她毫无畏惧地望着这股光芒，不过我已经看出她自信背后的一丝不安。那只手伸向她，用手指罩住了她的脸庞。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (201, '斯温的妻子像一尊雕像一样直直地站在那里，眼睛睁得大大的。虽然她的嘴唇张开着，似乎是在尖叫，但是她却始终无法发出声音。过了一会儿，那只折磨着她的手终于松了下来，把她丢在地上。拿着宝石的那个骑士巍然正坐在马鞍上，一个声音从他口中传出。$B$B「这个女人在撒谎，」那个可怕的声音时常在我梦里出现，「她没有见过镰刀。」') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (202, '然后，骑士的肩膀瘫软了下去，好像躯壳中的灵魂突然离它而去。随后，那个苍老而尖厉的嗓音又响了起来，他说的最后一句话是:$B$B「大人下令了，杀掉他们。」') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (207, '从罗兰之墓侥幸逃出来后，我躲在一个斯温家的谷仓里。我在那里面过了好几个星期，一直都被恐惧所笼罩，也不敢让斯温和他的家人知道我的存在。虽然从我对他们的观察来看，这些农夫都是些很本分的平民，而且如果我从藏身的地方走出去，他们也一定会接纳我住在他们家里，不过对我而言，要信任别人是十分困难的─尤其是经历了矿坑里那恐怖的一幕之后。$B$B因此我躲在那儿，一直没有现身。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (208, '<书中剩余的部分是空白的>') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (209, '报告:狗头人$B$B北郡山谷中狗头人的活动日益减少。所有的狗头人都被狂暴的黑石兽人赶走了。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (210, '报告:黑石兽人$B$B黑石兽人的侵略部队出现在山谷之中。他们的攻击似乎是某件更为阴险的事件的前兆。请警告湖畔镇的所罗门镇长。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (211, '报告:关于狼群$B$B关于狼群袭击北郡的报告最近有所增加。伊根认为狼群数量的增加主要是由于许多狼都从暮色森林来到了山谷中。$B$B虽然狼群很少袭击人类，但是它们数量的激增给农夫增加了很多麻烦。这段时间来已经发生多宗家畜失踪事件了。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (212, '嘉奖:$B$B传递此公文者将会被授予暴风城军队代表的头衔，以证明他/她曾全力帮助过北郡。我相信您将会发现这个人也可以帮助艾尔文森林。$B$B署名:$B- 治安官杜格拉斯·玛克布莱德，$B暴风城防卫军，北郡') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (213, '西部荒野炖肉$B$B3份秃鹰肉条$B3个血牙野猪的头$B3颗鱼人的眼球$B3根秋葵$B$B把以上各种材料都混在一起烹煮至少两小时后方可食用。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (218, '我担心斯通菲尔德和马科伦家族之间的勾心斗角会毁掉汤米·乔和梅贝尔之间的爱情，在现在这个时代中，即使面对再多黑暗的威胁和战争的阴影，我们也应该努力去呵护爱情和年轻的生命。$B$B所以，我希望你能帮忙制作一些隐身药水，让这两个年轻人能够相聚。$B$B谢谢你，威廉。还有，当你空闲的时候别忘了多来我这里玩玩。我们已经有好久没见过面了，我十分怀念以前与你一起度过的快乐时光。$B$B- 米莱德') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (219, '由暴风城建筑官员巴洛斯·艾力克斯顿亲自提交$B$B陛下:$B$B我之所以写这样一份报告，是因为我觉得应该对迪菲亚兄弟会这个组织最近的动向及其在王国领地内的所有活动向您做一汇报。$B$B为了把他们的情况解释清楚，请允许我首先介绍一下这个组织的一些背景。或许您并不知道，我以前曾是暴风城石匠公会的会员。经过多年的辛勤工作，我们完成了暴风城的重建，而石匠公会却没有收到分毫的报酬，甚至根本没有人提及。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (220, '当时任石匠公会会长的艾德温·范克里夫多次索要暴风城拖欠的报酬，而暴风城贵族议会的回应却是命令石匠公会解散，这当然激怒了范克里夫。他发起了一场暴乱，带领石匠公会的人离开了暴风城。$B$B在我继续讲述之前，还有一些发生在那时的其他事情应该让你了解一下。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (221, '首先，正是在那个时候，暴风城的贵族向我许诺说，如果我能脱离范克里夫的组织，他们就可以让我担任城市建筑师的职位。由于和他的一些思想有分歧，我便选择了留在暴风城。$B$B暴乱期间，范克里夫最信任的助手巴基尔·斯瑞德被俘，一直关在监狱里等待审判和盘问，现在几乎已经被人遗忘了。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (223, '视需要决定是否公布以下消息。$B$B提里斯法林地区命令$B麦罗斯队长$B瓦松队长$B派瑞恩队长$B$B由大领主下达的命令。$B$B派瑞恩队长，进一步加强西南哨塔的防御(按计画行事)。更多的补给将在稍晚些时候送达。同时，在附近的农场征收必需的物资，并进行进一步的侦察和情报搜集工作。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (224, '应该可以收集到布瑞尔地区的不死生物活动情报。$B$B瓦松队长，北部哨塔一带的不死生物活动日益增加，必须快速果断地消灭这种活动。$B$B麦罗斯队长，瘟疫之地边界地区的不死生物正在不断集结。增援部队将在接下来的几周内到达你的辖区。$B$B沐浴在圣光的荣耀之下') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (229, '第1天$B$B我的坦克坏了，但是我知道我们要找的那种矿石就在山中的某个地方，我让塞克·锤足留在这里看着坦克。$B$B我要继续独自寻找。如果我不能回来的话，这将成为我最后的遗嘱。$B$B驾驶员莫里·铁钻$B铁炉堡攻城坦克旅') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (232, '第4天$B$B我的补给越来越少了。我有足够的食物，不过我从没想到会离开我的坦克在野外待这么久的时间，而且还只带了两小桶麦芽酒。$B$B前两个晚上我都没有睡觉，一直在听着那该死的咆哮声，我的酒都差不多喝光了!$B$B我明天得回到我们的坦克那儿去，我可不想在没有酒喝的情况下在这里迷路。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (234, '第6天$B$B那头熊没有回来─我一定是把它打成重伤了!不过我还能听到它的咆哮，它大概是在等着我死掉!$B$B不管是谁发现这本书，我都要托付给你一个任务。杀了那头肮脏的熊!杀了它，再把这本书交给我的朋友塞克·锤足，让他知道发生了什么事。$B$B拿着我的护甲，你会用得到它的!') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (243, '在搜集苔藓标本的时候，我经历了一场血腥的战斗。邪鳍部族的鱼人遭到了一群豺狼人的袭击，战场上留下了无数鱼人和豺狼人的尸体。我注意到某个鱼人的伤口上长着一个坚硬的肿瘤。仔细观察这个肿瘤之后，我发现它和我收集的苔藓的特性差不多。不幸的是，除了这具尸体之外，我在别的尸体上找不到类似的肿瘤了。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (244, '比索·埃斯沙德大人:$B$B遵照您的指令，我派遣这个$C来为您效力。$B$B$G他:她;非常可靠，而且听从指挥，在对付天谴军团的过程中证明了自己的实力，所以我选择$G他:她;来协助您完成任务。$B$B祝您安好，$B- 执政官塞弗伦') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (245, '失踪:基沙恩下士$B$B他在石望要塞的血腥战役中失踪，据说已被黑石兽人俘虏。$B$B基沙恩下士应该是被关押在湖畔镇北面的黑石营地中，也就是通往燃烧平原隘口的西边。$B$B根据所罗门镇长的命令，任何救回基沙恩下士的勇士都将受到治安官马瑞斯的嘉奖。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (246, '您好，主人。$B$B 请原谅我用这种方式给您写信。奥特兰克的暗影法师正在忙于他们的计划，我不得不使用外面的——从我们新的“盟友”中招募的——信差给您送信。但我用了我们最深奥的口令来撰写这封信的具体内容，所以由这些乡巴佬送信是非常安全的。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (248, '您好，主人。$B$B请原谅我用这种方式给您写信。我在奥特兰克的暗影法师正在忙于他们的任务，我不得不使用外面的─从我们新的『盟友』中招募的─信差给您送信。但我用了我们最深奥的密码来撰写这封信的具体内容，所以由这些乡巴佬送信是非常安全的。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (249, '瓦里克:$B管好那些奴隶，等我们回来。继续在这里保存它是很危险的。我们将到北方去，到一个不可能被发现的地方去。$B$B它们只不过是动物，不过是凶残的动物─只要它们有了一定的数量，我们就有大麻烦了。绝对不能让它们集结起来，这是我最不想看到的事情。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (251, '我的兄弟们，记住，我们曾经是值得骄傲的工匠。我们要用工匠惯有的缜密和谨慎来完成现在的任务。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (252, '恐怕当初我父亲决定留下来守卫家园是个严重的错误。亡灵的部队已经席卷了提里斯法林地，虽然我们做好了防御的准备，而且补给也很充足，但是由于我兄弟代弗林的背叛行为，现在我们缺少足够的人手来抵抗亡灵的不断袭击。$B$B伊维特，如果你接到了这封信，那么你一定要明白，代弗林是叛徒。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (254, '他们发起了凌厉的攻势。在我们干掉这些偷袭者之前，他们又杀了一个人。现在我们没有足够人来守卫边界。要不了多久，我们就会筋疲力尽，而亡灵又会发起攻击。$B$B虽然那天晚上我在那些拼死作战的人和面色憔悴的亡灵中看到了代弗林的脸，但是在我抓到他之前，这个懦夫就溜走了。也许他已经死了，也许他还活着，给亡灵当间谍。$B$B不管怎样，他都是个怪物。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (255, '代弗林警告过我们，与亡灵为敌必死无疑。早在我们被包围之前─大概就是亡灵刚刚进入提里斯法林地的时候，他就说过这话。也许他是想恳求我们离开，也许他是在幸灾乐祸。$B$B我总是很难理解代弗林的动机，他从小就是那么神秘。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (256, '不过他是对的，我们的确失败了，阿加曼德家族将会从此消亡。虽然我现在还活着，但我知道自己的死期也不远了。$B$B我并不害怕，也不后悔留下来和家人待在一起，不过我最后牵挂的还是你。$B$B你要好好活下去，我亲爱的伊维特，那样我才能安息，$B- 萨尔曼') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (257, '我们的计画进行得很顺利，正如以前提到过的一样，我们与一队自称辛迪加组织的人类结了盟。他们的首领以前曾是奥特兰克的贵族，他们希望能再次控制这里。$B$B因此，这些愚蠢的人类与我们达成了一个协议，他们将会为此而后悔。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (259, '完成了这一步，我们就可以开始下一阶段的计画。在拥有了自己的国家和这个地区的前沿基地之后，我们就可以为第三次入侵作准备了。$B$B不久，军团的首领将会表彰我们，让从天而降的烈焰吞噬整个世界!') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (262, '教师卢瑟福·博塞德$B债务已还清。$B$B铁匠埃沃里·维林塔$B债务已还清。$B$B书记员霍拉斯·怀特斯蒂$B债务已还清。$B$B议员吉利斯$B债务已还清。$B$B议员胡克斯$B债务已还清。$B$B农夫盖斯$B债务已还清。$B$B农夫雷恩$B欠款，收获时以农作物偿还。$B$B农夫莱恩$B欠款。租地被收回。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (263, '农夫卡拉巴$B欠款，收获时以农作物偿还。$B$B居民维尔克斯$B债务已还清。$B$B居民博诺安$B债务已还清。$B$B矿工威尔迪$B欠款，碧玉矿坑送来下批矿石时偿还。$B$B矿工西尼$B欠款，碧玉矿坑送来下批矿石时偿还。$B$B矿工哈克特$B欠款，碧玉矿坑送来下批矿石时偿还。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (265, '一支亡灵小队毫不顾忌人类和亡灵之间的对立关系，到我们这里来寻找他们的“同胞”。克甘达玛是这支小队的队长，他的皮肤已经腐烂，他的血液早已停止了流淌，但他却显得彬彬有礼，他对同伴安全的关心甚至胜于关心他自己。$B$B 实际上，我甚至觉得他拥有我周围的人已经丧失许久的人性。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (266, '一支亡灵小队毫不顾忌人类和亡灵之间的对立关系，到我们这里来寻找他们的「同胞」。克甘达玛是这支小队的队长，他的皮肤已经腐烂，他的血液早已停止了流淌，但他却显得彬彬有礼，他对同伴安全的关心甚至胜于关心他自己。$B$B实际上，我甚至觉得他拥有我周围的人已经丧失许久的人性。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (267, '但是我为什么要提到这个?我之所以这样做是为了表明我将要写下的东西是可信的，因为这些话来自克甘之口，我希望我的同胞看到这本日记，知道我为什么要相信他的话:$B$B「还有一些上古诸神在世界的深渊中游荡，新的势力在寻找支配这些古老力量的方法，谁成功了，谁就将得到一件可怕的武器去对付他的敌人。」') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (270, '我希望能够和我的同事通过研究证明那种石头确实具有某种魔法特性，如果达拉然的巫师不希望发掘血石的能量，那么我们至少应该了解它的特性，因为我们的敌人也许会利用血石对付我们。$B$B所以我的研究开始了。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (276, '看到这个，我的头脑一下子清醒了不少，也许是因为我的新伤口(虽然我不敢相信自己居然流了那么多血)，也许是因为在屡遭挫折之后终于发现了血石的秘密。我坐下来开始思考，脑中不断涌现各种想法和问题，这让我头晕目眩、摇摇欲坠。$B$B血石会吸收鲜血?它渴望鲜血吗?它还会吸引鲜血?') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (281, '在等待那里的实验结果的日子里，我又去找克甘谈了谈。尽管我不断逼问他关于血石的事，他却没有再多说一句。他也很少提及在他所属的不死生物群体─他称之为「被遗忘者」─那边度过的日子。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (289, '"祈伦托的大法师卡德加$B$B麦迪文的前学徒，进攻德拉诺兽人世界的联盟远征军最高指挥官。可能已阵亡。$B$B没有人能够如此无私地深入最黑暗而危险的战场。不管你在哪里，我们都希望你一路顺风，勇敢的探寻者。$B$B- 安东尼达斯 - 达拉然大法师"') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (290, '图拉扬将军$B$B安杜因·洛萨爵士的副官，白银之手骑士团的圣骑士，进攻德拉诺兽人世界的联盟远征军的大将军。可能已阵亡。$B$B「(古代语) - 我们以鲜血与荣誉来奉献。$B我的朋友，你是公正与美德的化身。你的名字将是我们永远的荣耀。」$B$B- 光明使者乌瑟 - 白银之手骑士团') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (291, '达纳斯·托尔贝恩$B$B激流堡的民兵指挥官，进攻德拉诺兽人世界的联盟远征军总指挥官图拉扬将军的战略顾问。可能已阵亡。$B$B「孩子，你的经历和牺牲将永远被我们铭记。自我们的光辉帝国建立之日起，英雄的鲜血便浸透了整个帝国的历史。」$B- 索拉斯·托尔贝恩，激流堡之主') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (292, '"光明使者乌瑟在此安息$B第一圣骑士 - 白银之手骑士团的奠基人$B$B乌瑟誓死保卫罗德隆王国，尽管他最心爱的学生背叛了他，但我们相信他的灵魂永生。即使厄运降临于我们的故土，他依然在关注着我们。他的光芒将照亮所有人类前行的路途 - 只要我们依然以他为榜样，它就永远不会消失。$B- 无名氏"') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (295, '这是否证明巨魔不愿冒险离开他们的领土，或是他们缺乏长途旅行所必需的相应技术?这一点还有待进一步研究分析，但它已经不是本文要探讨的了。$B$B不过有一样东西会引起所有人的注意，最近在荆棘谷的大片巨魔废墟中找到的线索显示了巨魔和大海相关的一面，这一面以前从未为人所知，也没有相关的史料记载。$B$B海潮之石$B$B最近在荆棘谷巨魔废墟中的发现涉及到了一件叫做「海潮之石」的东西。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (296, '将巨魔传说中的许多片段结合在一起，我们便可以得到关于这块石头的完整描绘、以及它对古老的古拉巴什帝国的重要意义。$B$B海潮之石似乎可以将支配各种形式的水的力量赋予其拥有者，包括对河流、雨水和潮汐等形式的支配。根据这些和海潮之石的用途有关的故事，我猜测它实际上是水之领主的力量的物质表现形式。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (299, '他可以借此召唤完全由水组成的生物:水元素─原本只有祈伦托的大法师才具有这种能力。$B$B这个战士来到了帝国的核心地带祖尔格拉布，向国王展示他的能力。显然，他迅速成为了全帝国关注的焦点。古拉巴什的国王也被他的能力折服，立刻给他封了一个荣誉职位:「控潮者」，而他原来的名字则逐渐被遗忘了。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (301, '随着时间的流逝，控潮者的身体开始渐渐消失。随着潮汐的每次涨落，他都会失落一部分肉身─身体一会儿出现一会儿消失─直到临死时，他来到了最初找到石头的那片海滩，步入大海，从此消失。$B$B又经历了好几代的时间之后，海潮之石再一次被冲到荆棘谷的海岸上，又被另一个控潮者拾得，然后这个巨魔又将它带到祖尔格拉布去。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (303, '血帆命令$B$B亲爱的水手们，请仔细看好这篇命令中的内容，因为我们在藏宝海湾发财的机会只有一次。$B$B我已经派邓肯守在北边，并告诉他等待行动的信号。$B$B达姆希的好运号将停靠在南边的海角旁等待补给命令。小个子的斯蒂沃特船长会让他的船员做好运送战利品的准备。我相信布鲁图斯那个蠢货会是我们最大的麻烦。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (306, '我让尼哈鲁船长把斩浪号从东南方向开到岸边去。等信号发出后，我们就让他的船员冲出来。$B$B加尔·盐蹄那个壮汉可以打前锋，我们要让里维加兹和卡拉·海角措手不及，把他们送到海底喂鱼去。$B$B你们几个负责把一切对范克里夫的计画有价值的东西都抢走。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (307, '我会命令艾隆帕开火，防止任何黑水海盗的船只进出港口。$B$B红雾号的弹药打光之后，我会将她开到斩浪号旁边对她进行补给。$B$B等盐蹄和他的人在镇子上放了火之后，所有人都回到船上去，我们就立刻开船，还可以在野人海岸给藏宝海湾再来一次炮击。$B$B- 舰队指挥官菲尔拉伦') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (312, '第5天:$B托尔森今天显得十分不安。一定是他昨天值勤途中遇到的什么人或什么东西让他感到恐惧。$B$B我以为我们的人已经和他谈过了，不过当我询问托尔森在我掩护他时去了哪里的时候，他却默不作声。他把我当作朋友，所以他认为不告诉我这个危险的秘密可以保护我。$B$B他的忠诚用错了地方，但是这种忠诚却十分强大。他和我们重新汇合之后一定会成为库尔森军队有力的增援。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (313, '第6天:$B一大早，托尔森与尤瓦中士进行了一次长谈。我不得不假装睡觉，因此不敢移动身体去偷听他们的谈话。但是我猜他们正在谈论托尔森前几天的那次值勤。$B$B我在午餐时近距离地观察尤瓦，发现他也在观察我。不久，多伦又叫上了托尔森。多伦和尤瓦肯定知道托尔森正在与你的人会面。$B$B他在为反抗军做间谍。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (314, '我们不能再给托尔森提供更多情报了，必须除掉他。他对我们已经不再有用。$B$B如果有机会的话，我会杀了托尔森，但是如果你收到了这封信，那就表示我还没找到机会。$B$B在这种情况下，我建议在托尔森与我们的人下一次见面时给他致命的一击。$B$B-M') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (316, '蠢货!$B$B我的计画是同时摧毁那两座桥。你们这些头脑简单的蠢货都干了些什么?你们只完成了一半的任务，还让整个联盟都对我们产生了警惕。你们全都是蠢货!$B$B你们只有一次弥补错误的机会。我们在离桥不远处的阿拉希高地还有个秘密据点，那里还藏有一些爆裂物。$B$B如果你们还想继续活下去，就得给我完成任务!$B$B- 卡姆·深怒') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (317, '我亲爱的萨拉:$B$B我想我们这几天要去看守萨多尔桥。也许我从此就无法再给你写信了，所以现在我很想给你写点东西，让你知道我在生命中最后的日子里都在想念着你。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (318, '我们的任务可能要持续好几天，并且充满了乐趣，但是对我而言，它也许意味着残酷的战斗和死亡。如果我必须在战场上为联盟而牺牲的话，那么我随时都作好了这种准备。$B$B对于我所从事的事业，我充满了信心，勇气永远与我同在。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (319, '我知道铁炉堡王国非常需要联盟的胜利，而我们欠那些在恶魔战争中浴血奋战的牺牲者很多东西，我多么希望能放弃此生所有的快乐去维系这个联盟，并还清欠那些牺牲者的债。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (320, '萨拉，我对你的爱是永远不灭的，它如同无形的绳索束缚着我，没有东西能够解开它。而我对王国的热爱则像强风一样袭来，让我在战场上也无法不想念着你和我们的家园。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (321, '我不断想起和你一起度过的美好时光。我感激圣光，也感激你。我和你度过了那么多美妙的日子，而现在我却不得不放弃这一切。我们本来还可以生活在一起，相亲相爱，看着我们的儿子在身边慢慢成长，然而现在我不得不放弃这些希望，这对我来说是多么困难的一件事啊。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (322, '我对于我神圣的使命没有什么抱怨，不过我总是听到有人在对我轻声低语─也许是风吹来了我的小爱德格的祈祷，它告诉我一定要安然回到我所爱的人身边。我亲爱的萨拉，如果我不能回去，请你不要忘记我对你的爱有多深。即使我在战场上永远停止了呼吸，我也会在那之前轻轻呼喊你的名字。$B$B请原谅我以前所犯的错和我给你带来的那些痛苦，我那时总是那么愚蠢，那么自私。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (323, '如果我能用眼泪清洗影响你快乐的那些污点，如果我能和这个世界上的所有灾祸斗争，保护你和我心爱的孩子免受伤害，那对我该是多么快乐的事啊。$B$B但是我做不到。$B$B当你带着我们的孩子与残酷的命运斗争时，我会在扭曲虚空中看着你，在你身边徘徊，悲伤而又耐心地等待着我们再也不用分开的那一天。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (336, '施耐德:$B$B你好。我相信运河地区的生意很兴隆，我们这儿的贸易区一直都很热闹。$B$B我们的存货几乎都用光了，现在急需布匹。请你尽快为我们供货。$B$B祝你好运，另外，希望你的孩子萨尔曼学业进步。$B$B- 哈兰·巴格雷') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (338, '同时，我还派出了阿维罗德上尉，在卡林多大陆执行侦察任务。他的部队完成任务之后，会与我们在提拉加德城堡的部队会合。$B$B阿维罗德上尉的任务可能需要很长时间，因为这片新大陆幅员辽阔、充满危机。如果我或者本尼迪克遭遇不幸的话，阿维罗德将接手城堡的指挥权。$B$B我们会发动一轮接一轮的攻击，直到占领这座要塞!$B$B- 普劳德摩尔上将') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (340, '部落征兵通知$B$B持此通知者已被证明具备出众的力量和战斗技巧。我建议将其分派到十字路口去执行任务。$B$B- 塔克林·寻路者谨上') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (341, '<HTML><BODY><H1>部落征兵通知') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (350, '主动式负载平衡器控制台可以自动调节燃料、燃气、液体的流动及相关的机器设备。在完成了初始化设置之后，只需简单维护即可进行日常的运行。$B$B控制台的主要部件(从左到右)依次是:$B$B主动力杆$B$B处于连接位置时，启动主动式负载平衡器。将动力杆调至「关闭」位置时，机械装置也不会自动松开，它只会') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (351, '菲兹普罗克主管，你提交的设备申请表已经拉兹杜克总裁批准。$B$B 他让我提醒你注意风险投资公司在整个卡利姆多大陆的既得利益。我们在贫瘠之地的钻井和采矿业是有利可途的，而且效益卓着，但是你所管辖的莫高雷地区还是需要为我们提供足够的生产量。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (354, '除了采矿，我们还希望莫高雷分公司能够提供木材，另外还为你提供了原材料和几台新型粉碎机，用以建立一座伐木场。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (355, '进入冷却过程，要等一到两分钟才会完全关闭(视实际情况而定)。$B$B特别注意:只有当机器上的三个控制阀都松开的时候才能操作主动力杆。这些控制阀可以按照任意顺序关闭。$B$B第一个是主控制阀，在垂直的巨大烟窗底部。接下来是燃料控制阀，在燃料箱(应有三个)和烟窗之间的管道上。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (357, 'IV.流量控制器$B$B升高或降低流量。由主动式负载平衡器自动控制。$B$BV. 温度指使计$B$B显示系统的操作温度。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (358, '星辰的孩子已经在永恒之井闪光的湖水边定居了很久。众所周知，象征永恒曙光的伊露恩在就在这水中休憩。岸边住着星辰的孩子们，伊露恩眷顾着他们，给他们安家，而他们也总在夜晚虔诚地凝望月空。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (361, '德尔葛兰大人:$B$B事情正像您所担忧的那样。您关于奥萨拉克斯之塔的猜测是正确的。有一群邪恶的信徒聚集在奥萨拉克斯之塔一带，他们当中有许多术士，甚至还有一个凶残的萨特。我不清楚是何种邪恶的力量将他们聚集在一起，但是我对此感到十分忧虑。$B$B他们自称是暗滩教派的信徒。$B$B请原谅我这封信写得很简短，但是危险正潜藏在森林中，我只能简单地描述一下这里的情景。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (377, '达古恩之手$B$B达古恩是深海中的一种巨兽，它为尘泥沼泽的鱼人所崇拜。它们的萨满对一种特殊的海藻施了魔法，然后用这种海藻把达古恩引到水面上来。去猎杀那些鱼人，从它们身上找到附有魔法的海藻，然后把它放在鱼人的祭坛上，然后等待达古恩出现。$B$B我需要他的手。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (380, '亡灵哨兵任务报告$B$B侦察员:兰妮·尤瑞克, 奎恩·尤瑞克, 埃兰德·玛科雷$B$B主要任务:完成对银松森林北部的侦察工作，并且判断天谴军团和野生动物的威胁程度。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (381, '侦察员发现了大量狼人的存在。建议派出捕猎小队扫除这个威胁。$B$B在亡者旷野的农场上发现了不死生物豺狼人。虽然我们还不知道它们在农场聚集的目的，但是根据其动向和准备程度来看，它们很快就有可能开始军事行动。在我们观察豺狼人的这段时间里，并未发现它们当中有明显的首领。也许它们是在等待指挥官或是增援的到来。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (386, '另外，这位信差不仅协助我们完成了任务，而且帮助我们击败了邪恶的伊瓦、营救了埃兰德，并且负责递送了这份报告。$B$B 我们对$G他:她;充满感激之情，希望上层能对其卓越表现给予相应的嘉奖。$B$B - 亡灵哨兵兰妮・尤瑞克$B 行动负责人') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (394, '一个邪恶的力量造成了这一切$B他的元素生物永不停歇$B他悠闲地坐在鬼雾峰上$B对着你露出轻蔑的笑容$B$B你很快就要面对这个法师$B只有他的死亡才能终结这件疯狂的事') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (395, '迈萨迪斯神殿$B$B「愿伊露恩之光如远古时那样永远照耀着山谷，照亮森林中的道路。」') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (396, '月神满足了我的愿望。我的同伴不应白白牺牲，我将用月神镰刀为他们复仇。这是一件古老的物品，一根粗糙的螺旋状的木头，可能比卡多雷还要古老。$B$B我花了很长时间来研究神赐给我的这件东西。它不是一件普通的武器，也不是一个简单的法器。有了它……仿佛时空的障碍都变得微弱了许多。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (422, '风险投资公司的函件在矿坑的外面……可能在底层的什么木箱里。$B$B祝你好运，记住……$B$B蓝色炸药:伐木场$B红色炸药:矿坑$B$B哦，完成任务之后别忘了把信也毁了。嗯，也许我该想个办法让这些东西在被人读过之后就自我销毁，这个主意不错……') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (428, '-- 第四天 --$B$B我被抓住了!$B$B必须……赶紧……写下来。$B$B我被剃刀部族的野猪人袭击。我以为他们会把我带到野猪神只的遗骸所在处。不过，他们却绕过它，从野猪神只遗骸的正西边穿过黄金之路前进。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (436, '「订单号:45TK-3$B买家:克拉维尔·浓须$B$B发货单:$B$B水棘轮 (3)$B转发栓 (50)$B30"20-线规铜管 (12)$B深怒牌鼻烟粉 (1)$B高级棱镜 (3)」') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (437, '我很想亲自把信交给您，不过我担心如果我离开这里的话，也许会错过一些重要的事情。$B$B如果你想要了解到更多关于奥萨拉克斯之塔的资讯，可以问问递送这封信的信差，$G他:她;协助我完成了任务，你应该可以信任$G他:她;。$B$B巴苏尔·影击') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (439, '菲兹巴布先生:$B$B送来这封信的$R和我希望您能够参与我们的一桩生意。$B$B正如您所知道的那样，我在闪光平原上待了不少日子了─我刚刚提到的生意是和这里进行的赛车比赛有关的。$B$B如果赛车以及与之相关的赌博能让你感兴趣的话，那就请继续读下去，我相信您的知识对于我们的计画来说是非常有用的。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (440, '菲兹巴布先生:$B$B您交给我的合作人的那些酒非常棒。酒味醇厚，而且很容易让人上瘾。我相信喝过它的人一定会想要喝更多的。$B$B我们为此向您表示感谢，克兰克。$B$B我诚心邀请您来闪光平原来和我们一起把握这里的赌车机会，或者如果你公务繁忙的话，也可以让某位好友来这里玩一玩。$B$B- 克拉维尔') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (441, '善良的马特克:$B$B现在我遇到了一些困难，所以需要你的帮助。$B$B我兄弟和我要造一辆赛车，所以我们需要一些强力的活塞。我试过的那些都不够结实，用那种破玩意根本没办法把我们新车的速度给提起来，而且引擎还老抛锚!$B$B你是最优秀的金属工匠，你一定能帮上忙，而且你是我们唯一的指望啦!') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (442, '如果你想要找到霜喉的话，就必须用它最喜欢的食物把它引诱出来。$B$B前往奥特兰克山脉，在那里杀掉一只巨型山地狮，把它的肉带到无草洞去，那是雪怪的圣地。$B将山地狮的肉放到尤基尔之焰上烧烤，很快，香味就会引来霜喉。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (446, '如果我们能够控制哪辆车的状态好哪辆车的状态糟的话，那么……我想，不用再多解释，你也应该知道这对于我们赌车有多大的好处。$B$B所以，善良的菲兹巴布，我们需要由你来找到一种能把他们的工作人员搞糊涂的方法。$B$B你知道荆棘谷里有什么植物、药草或者饮料可以让侏儒和地精们变成笨蛋吗?$B$B- 克拉维尔·浓须') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (448, '药剂师林度恩:$B$B我希望这封信能安然地送达你那里，遥远的卡林多大陆需要你的帮助。$B$B现在在离我们牛头人盟友的老家莫高雷地区很近的石爪山一带出现了重大的危机，地精风险投资公司在山里肆意砍伐树木，开采矿物，这已经激怒了那里的山灵。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (449, '我猜想牛头人萨满和德鲁伊正在努力平息这些山灵的愤怒，牛头人认为石爪山的地精风险投资公司是个可怕的威胁。$B$B无论他们的观点是否正确，我们都必须去帮助我们的盟友。$B$B林度恩，你在毒药方面颇有建树，能否推荐一种可以在石爪山的地精中传播的毒药?$B$B札玛') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (458, '奈萨里奥:$B奈萨里奥被称为大地的守卫者，他比其他的守护巨龙更加兢兢业业地守卫着艾泽拉斯世界。他的黑龙军团的职责是创造山岭，以及为各种普通的种族构筑疆界。他的堕落至今仍然是个谜，究竟是外在的原因还是内在的原因造成了他的堕落，这一点尚无定论。我猜想，上古诸神也许曾涉足其中。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (467, '恭喜您!$B$B您已经成为了这只地鼠的新主人!虽然它看起来很害羞，但我们确信您会发现它非常可爱，而且具有出色的能力。$B$B在接下来的几页中，您将找到关于地鼠的详细资讯:$B$B1. 喂食和照料须知$B2. 奇怪(而且可爱)的习惯$B3. 地鼠指挥棒(tm)的使用 $B$B再一次对您表示祝贺。您是绝对不会对它失望的。$B$B- 玛维格·铜拴$B地鼠有限公司') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (528, '乔贞:$B我的担心变成了现实，他们以我没有想到的方式行动了。我从来没有想过他们能够做到这一步，但他们确实做到了。$B$B请指点给你带来这封信的信差，让$G他:她;去找那个人。他会帮助我们的。假如事情不是这么紧急，他会继续袖手旁观，但这次他肯定不会。$B$B谢谢你，老渔夫，你总是那样无私地帮助我。$B$B你的朋友，$B德拉维') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (547, '乔贞:$B我的担心变成了现实，他们以我没有想到的方式行动了。我从来没有想过他们能够做到这一步，但他们确实做到了。$B$B请指点给你带来这封信的信差，让$G他:她;去找那个人。他会帮助我们的。假如事情不是这么紧急，他会继续袖手旁观，但这次他肯定不会。$B$B谢谢你，老渔夫，你总是那样无私地帮助我。$B$B你的朋友，$B德拉维') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (573, '这些瘟疫炉被一群忠诚的教徒所守卫。而瘟疫炉将会散播瘟疫到整个罗德大陆北方，不论乡村或都市都将受瘟疫所苦。$B$B巫妖王的计画目前进展非常顺利。目前瘟疫已经在大陆北部的许多村落中爆发了。与北裂境大陆目前的状况完全相同，所有感染上瘟疫的人都已经死亡，成为巫妖王的奴隶。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (582, '「最好在离其目的地不远处下手，据说我们的「盟友」也埋伏在那一带。我真是不明白，我们为什么要和那种生物结成同盟，但我也没有什么办法，我们是迫不得已。不过算了，这也没什么。只要我们能牢牢揪着目标，就一定可以从暴风城那里，拿回当初他们从我们手中偷走的东西!」') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (639, '这个当时尚未开化、过着游牧生活的类人生物族群，被井中的奇异能量所吸引而来，在宁静的岸上建立永久性的居所。日复一日，受到井中大宇宙力量的潜移默化，他们更加强壮、睿智并获得不朽的生命。这个部族自称为卡多雷，在他们的语言中意为「星辰之子」。为了庆贺文明的诞生，他们沿着湖泊建起雄伟的居所与庙宇。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (649, '- 漂亮的边缘,长度从拳到肘。$B$B- 边上是银色的铆钉。$B$B- 中间有一枚三指宽的银色大铆钉。$B$B- 橡木材料,用铁强化。$B$B- 把我的名字,格林戈·雷矛,嵌在盾牌顶部边缘。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (650, '我们会以一如往常的方式支付。此外，请给这位信差支付一份标准的报酬，您可以把它算进盾牌的价格中。$B$B非常感谢!$B您真诚的格林戈·雷矛') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (682, '一旦进入适当的地区，瘟疫病毒便会渗入地表，然后在无辜的市民间传播开来。在科尔苏加德的执行下，巫妖王的军队迅速壮大，并控制了罗德隆的大部分土地。这支军队就是天谴军团，它的唯一目标，就是令艾泽拉斯大陆上的人类彻底灭绝。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (692, '过着充满爱和善行的平静生活。 您施舍穷人，治愈病人，安慰垂死的人。 你满心欢喜地等待着，坚信你将获得永恒和平的来世。$B$B你被背叛了。$B$BI无法给你带来安慰。 另一方面，复仇完全在我的能力之内。 来到丧钟的古老教堂，我将教你如何通过你所学到的信仰造成致命的伤害。$B$B - 黑暗牧师 Duesten，牧师训练师。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (693, '陶醉在你新的不死状态中，运用你的力量清除世界上那些想要消灭我们的人。 虽然我们的敌人数量众多，但我们会用火焰和阴影消灭他们。$B$B当你准备好让我教你黑暗和召唤之道时，你会在古老的丧钟教堂找到我。$B$B -Maximillion， 术士训练师。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (696, '日记 - 第4天$B$B我已经在这个岛上被困4天了，我很孤独，只有我的思想与我为伴。香蕉的味道很好，但我得爬上很高的树才能摘到。等到我不能再去寻找食物，也不能再保护自己免受阵雨之苦时，我满脑子想的，都是如何逃出这里。$B$B要是不再有纸和瓶子被冲上海滩来，我就要彻底绝望了。我坐的那条该死的船，居然装满了链金药剂和药方，它们对我一点用都没有。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (697, '日记 - 第512天$B$B我最近和香蕉们聊了很多，我也从它们的话中了解到了，许多有关它们文化的东西。我对自己无意之间，毁灭了它们的家园、吃了它们的孩子，表示万分的歉意。对于这个差点被我毁灭的文明，我了解得实在是太少了。$B$B似乎我的纸和瓶子都快用光了。我第一次看到海滩上堆着的这些纸和瓶子时，还以为是取之不尽用之不竭的呢。我的生命快要结束了，我的日记也是。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (699, '$B我写这本书的目的，就是将这些东西仔细归类，这些来自异世界的恶魔，其唯一目的，就是摧毁我们的世界，所以当冒险者们遇到它们时，一定要准确地认出它们来。$B$B所以，如果你也愿意承担起保卫艾泽拉斯的职责，就请仔细阅读这本书，以了解你的敌人。$B$B- 乌尔$B达拉然法师') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (701, '在你将这些故事，不屑一顾地当作耳边风前，请容我告诉读者们:狼人是确实存在的。它们或许与我们处在不同的世界中，但他们的家乡与我们的世界之间，却存在着某种通路，而某种强力的魔法力量，则可将狼人带到我们的世界中。$B$B这种魔法最好永远无人通晓，因为狼人所到之处，留下的只有恐惧与鲜血。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (703, '狼人生存之处，是个充斥着梦魇的黑暗世界。若你要问，那个世界上，有什么地方能免于狼人的肆虐，据我的研究显示:没有。$B$B其实，只要想一想，狼人这种生物，是多么的残忍与邪恶，就知道那是不可能存在的了。$B$B不过，狼人似乎很满足于留在自己的世界里，尽管它们中间的一部分成员，掌握着强大的魔法力量，却从未试图向艾泽拉斯进军。$B$B天下之幸，莫此为甚。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (704, '正如上述，某些狼人有高超的魔法造诣，而且他们的魔法中，蕴涵着黑暗与堕落的力量。$B$B诅咒与超自然的毒素，是他们经常耍的把戏，所以，面对这些狼人魔法师时，你必须有对抗暗影魔法的准备。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (711, '赫格拉姆，$B$B无论是谁提议，在荒芜之地的卡加斯建立一片基地，都将得到我的赞同。这个计画将使我们在那里拥有常备的驻军。那里的天气很糟，到处都是凶恶的野生动物与好战的土着，也没有什么补给，惟有我们最好的战士与斥候，可以在那里立足。$B$B这计画很好。干得漂亮。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (731, '<HTML><BODY><BR/><BR/><H1 align="center">伊莉莎</H1><BR/><BR/><BR/><BR/><P align="center">亲爱的妻子，希望大地可以抚慰你饥渴的灵魂。</P></BODY></HTML>') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (750, '<HTML><BODY><BR/><BR/><H1 align="center">伊莉莎</H1><BR/><BR/><BR/><BR/><P align="center">亲爱的妻子，希望大地可以抚慰你饥渴的灵魂。</P></BODY></HTML>') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (751, '活塞的技术参数:$B$B长度:32胡展$B宽度:12胡展$B重:23.5豆克 - 25.5豆克$B传导:70趾曲$B杆部强度:大于等于98$B连结指数:烈酒级或更高$B$B若你忘了侏儒的度量衡单位，说明如下:$B胡展=一根胡子的长度$B豆克=一块鹰嘴豆的重量$B趾曲=脚趾的曲度') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (791, '身为卡加斯派出的斥候，我对周围环境的描述如下：$B$B - 红色的岩石丘陵与干燥的平原，只有极少数生物才能在此生存。$B - 阳光炽烈，强风。$B - 没有湖泊和溪流，也没有任何池塘。想要找水的话，就必须挖出泥泞的深井，或者从仙人掌与其它针刺类植物中榨水。$B$B 简而言之：燥热，难以生存。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (793, '不用说就知道，我们卡加斯卫戍部队对能够被部署在这里感到非常高兴。我们已经在这里坚强地扎下了根，因为只要我们略微示弱，就会死在这里。$B$B 在这里也没有别的办法可以生存下去了。$B$B 尼卡・血痕$B 斥候队长，卡加斯') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (794, '我们的世界有着悠久的历史，一段由新生与古老的种族共同谱写的历史，一段神祗之间互相征伐的历史。$B$B一段秩序之神从天而降的历史，一段有关长眠地下的上古诸神的历史。$B$B我要讲述的就是这些上古诸神的故事，他们在艾泽拉斯世界形成之初就居住于此。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (796, '上古诸神是这个世界最早的主宰，他们控制了所有的力量。虽然他们现在被困住，处于长眠之中，但他们的仆从依旧在横行，而我们弱小脆弱的凡人，是无法和他们的力量相比拟的。$B$B胆敢挑战他们的蠢货都被吞噬了。只有那些为了自保而去逢迎上古诸神的仆人的人才能生存，虽然其代价是牺牲自己的灵魂和意志……') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (831, '在接下来的几页中，你可以找到制造淬火护甲所需的各种材料清单。祝你好运，战士。$B$B- 弗伦·长须') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (832, '烧焦的蜘蛛牙:$B$B在瑟根石附近的一个洞穴中发现的火岩矿石对栖息在那里的蜘蛛产生了烧灼影响。$B$B它们毒牙中的毒素被蒸发，并与牙齿本身产生了反应，因而造就出了一种非常坚硬的物质。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (833, '烧焦的奇美拉角:$B$B与烧焦的蜘蛛牙类似，卡林多石爪山地区的焦炭谷中有许多奇美拉，它们身上的烧焦的奇美拉角也有着惊人的高品质。$B$B只要把它敲平并进行妥善的处理，它就将是最具延展性的上好材料。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (834, '光滑的奇美拉角：$B$B 光滑的奇美拉角非常稀有，也非常坚硬，我可以用它制造出浑然一体的整片铠甲来，所以这种材料是我必需的。$B$B 你可以在焦炭谷中的奇美拉身上找到这种材料。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (835, '燃素：$B$B 制造铠甲的最后一步需要用到一种特制的高温炉。要生成那种程度的高温，必须要使用燃素才行。$B$B 我知道的唯一一个会制造这种东西的工匠是个名叫鲁古格的野猪人，恐怕你得打败他才能拿到东西。鲁古格就住在贫瘠之地南方的剃刀沼泽里。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (850, '在接下来的几页中，你可以找到制造淬火护甲所需的各种材料清单。祝你好运，战士。$B$B- 弗伦·长须') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (851, '烧焦的蜘蛛牙:$B$B在瑟根石附近的一个洞穴中发现的火岩矿石对栖息在那里的蜘蛛产生了烧灼影响。$B$B它们毒牙中的毒素被蒸发，并与牙齿本身产生了反应，因而造就出了一种非常坚硬的物质。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
