INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (853, '光滑的奇美拉角：$B$B 光滑的奇美拉角非常稀有，也非常坚硬，我可以用它制造出浑然一体的整片铠甲来，所以这种材料是我必需的。$B$B 你可以在焦炭谷中的奇美拉身上找到这种材料。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (854, '燃素：$B$B 制造铠甲的最后一步需要用到一种特制的高温炉。要生成那种程度的高温，必须要使用燃素才行。$B$B 我知道的唯一一个会制造这种东西的工匠是个名叫鲁古格的野猪人，恐怕你得打败他才能拿到东西。鲁古格就住在贫瘠之地南方的剃刀沼泽里。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (876, '科尔宝石:从我所知道的一些传说来看，这种宝石是法师用来储存能量所用的，这可以极大地增强他们的力量。我曾经帮助过一个名叫桑迪斯·织风的暗夜精灵，他可以告诉你更多有关宝石的资讯，只要你和他提到我，他就一定会帮忙的。我相信这些宝石中一定蕴藏了可以帮你铸造武器的力量。$B$B我和桑迪斯上次见面的时候，他住在黑海岸的奥伯丁，那里是暗夜精灵的家园，周围都是被污染的森林。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (877, '科尔宝石:从我所知道的一些传说来看，这种宝石是法师用来储存能量所用的，这可以极大地增强他们的力量。我曾经帮助过一个名叫桑迪斯·织风的暗夜精灵，他可以告诉你更多有关宝石的资讯，只要你和他提到我，他就一定会帮忙的。我相信这些宝石中一定蕴藏了可以帮你铸造武器的力量。$B$B我和桑迪斯上次见面的时候，他住在黑海岸的奥伯丁，那里是暗夜精灵的家园，周围都是被污染的森林。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (891, '这张手卷上画满了旋转的记号和复杂的象形文字，这些奇怪的符号让你难以理解。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (953, '星辰的孩子已经在永恒之井闪光的湖水边定居了很久。众所周知，象征永恒曙光的伊露恩在就在这水中休憩。岸边住着星辰的孩子们，伊露恩眷顾着他们，给他们安家，而他们也总在夜晚虔诚地凝望月空。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (954, '当森林中的古树被连根拔起的时候，由塞纳留斯的儿女们看守的树林，还有星辰之子们的石塔，整个世界都在颤抖。我们的女王即使在绝望和混乱的战争期间仍保持着她的优雅。在魔法的作用下，天空都变了颜色，爆炸好像要将世界撕成碎片。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (972, '奥达曼，第五日$B$B……那头穴居怪拿着从它那被杀掉的同族身上抢来的黄玉进入了大厅前面的侧室……$B$B……它把黄玉放进了一只很显眼的、正对着墓室后面的石棺中……$B$B……不过，有三个矮人守在那里!他们挡住了穴居怪的去路。引起他们的注意无异于自杀，我真怕现在这样虚弱的我被穴居怪一口给吞了。不过，如果我知道了第三块宝石的下落，我就要……') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (1031, '<HTML><BODY><BR/><BR/><P>纪念我亲爱的良师，霍拉迪·蒙特高莫，医学博士。一位医者，老师，朋友。</P><BR/><H1 align="center">50 BTFT - 25 ATFT</H1><BR/><P>"世界充满了病痛与疲惫。这是我们的工作，身为医者，同时，也是男人与女人的良药，净化他们的苦痛。" </P><BR/><P>- H.M.M., M.D., PhD, JD, 农夫大师，非凡的舞蹈家，动物的朋友$') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (1053, '显然，正是克拉文锁在箱子中的东西对塔中的居民产生了有害的影响。我猜测其他的守卫体内也应该有着同样的恶臭，而且，有可能连克拉文自己也已经成了这种影响的牺牲品。$B$B密探安玻·吉尔妮$B军情七处 国内行动八组') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (1071, '指挥官:$B$B速回奥格玛。现在不宜采取行动，我们必须根据最新情报重新分析我们的战略部署。$B$B在那里有很多影誓者和巨魔出没，还有许多恶魔守护着黑暗之门。$B$B- 索尔，部落大酋长') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (1090, '显然，正是克拉文锁在箱子中的东西对塔中的居民产生了有害的影响。我猜测其他的守卫体内也应该有着同样的恶臭，而且，有可能连克拉文自己也已经成了这种影响的牺牲品。$B$B密探安玻·吉尔妮$B军情七处 国内行动八组') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
