INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (1151, '风险投资公司<字迹模糊的文字>看来那些笨蛋为了稳定混合物几乎把整个计画都搞砸了。$B$B<接下来的几页都已经被撕碎>') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (1154, '马迪亚斯·肖尔派了个蠢货来刺杀我。<字迹模糊的文字>$B$B他现在正在外面为我巡逻，而且是个没有脑子、没有生命的傀儡。$B$B哈哈哈!') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (1155, '范克里夫……<字迹模糊的文字>$B$B召唤我?!我是克拉文·摩特维克!我怎么会被你这样一个无名小辈指挥!$B$B<这本书剩余的部分都不见了>') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (1156, '克格尔:$B$B我一直都在急切盼望着得到你的最新发明，我已经等不及要用它来记录我的研究成果了!$B$B请将你的发明交给我的信差。$B$B此致$B$B达蕾恩·轻风') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (1191, '重要资料!安全等级5122!$B$B01001001 01100110 00100000 01111001 01101111 01110101 00100000 01100011 01100001 01101110 00100000 01110010 01100101 01100001 01100100 00100000 01110100 01101000 01101001 01110011 00101100 00100000 01111001 01101111 01110101 00100111 01110010 01100101 00100000 01110011 01110100 01100001 01101110 01100100 01101001 01101110 01100111 00100000 01110100 01101111 01101111 00100000 01100011 01101100 01101111 01110011 01100101') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (1192, '决不能让以下资讯落入敌人手中!$B$B01010100 01101000 01100101 00100000 01100111 01101110 01101111 01101101 01100101 00100000 01101011 01101001 01101110 01100111 00100000 01110111 01100101 01100001 01110010 01110011 00100000 01101110 01101001 01100111 01101000 01110100 00100000 01100101 01101100 01100110 00100000 01110101 01101110 01100100 01100101 01110010 01110111 01100101 01100001 01110010') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (1193, '安全等级10^10000，最高机密!$B$B01001000 01100101 01101100 01110000 00100001 00100000 00100000 01001001 00100111 01101101 00100000 01110100 01110010 01100001 01110000 01110000 01100101 01100100 00100000 01101001 01101110 00100000 01100001 00100000 01100010 01101001 01101110 01100001 01110010 01111001 00100000 01110000 01110101 01101110 01100011 01101000 00100000 01100011 01100001 01110010 01100100 00100000 01100110 01100001 01100011 01110100 01101111 01110010 01111001 00100001') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (1211, '遛地鼠$B$B地鼠喜欢狭窄黑暗的地方，它非常害羞。$B$B如果您希望让地鼠到处走走的话，那么您一定要把它带到有家的感觉的地方，要让它闻到它最喜欢的食物─蓝叶薯的味道!$B$B这附近最适合的地方就是剃刀沼泽附近的沟槽。如果您在那里打开笼子，您的地鼠就会闻到周围蓝叶薯的味道，然后它就会走出来跟着您了。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (1213, '我们所有的地鼠都经过严格训练，您只需简单地挥动指挥棒，就可以让身旁的地鼠进入「搜索状态」。它会用嗅觉搜寻蓝叶薯，并会自己去把它挖出来。$B$B如果您在地鼠搜索蓝叶薯的时候再次挥舞指挥棒，那么它就会停止搜索，回到您的身边。$B$B我们相信您一定会发现我们的地鼠都是经过严格训练的搜寻专家，实乃居家旅行、发财致富的必备伴侣!') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (1214, '对我们地鼠有限公司来说，最让我们伤心的是，我们收到报告说有一些贪婪的蓝叶薯猎人不顾自己宠物的安全，把它们送入危险的地方搜寻蓝叶薯。$B$B我们决不能宽恕这样的行为，但是为了保证顾客对我们售出的每一只地鼠满意，我们郑重承诺:所有购买本公司产品的顾客都可以拿着购买凭证随时领取新的地鼠。$B$B祝您狩猎愉快!') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (1231, '这份契约是为了证明$N杀掉灼热峡谷中的一大祸害:狂暴的玛尔戈。$B$B铁炉堡博物馆特此颁发奖状，以表示我们对此举的认可，并对这份奖状的获得者表示感谢。$B$B- 馆长 杜里奥斯·裂石') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (1270, '对我们地鼠有限公司来说，最让我们伤心的是，我们收到报告说有一些贪婪的蓝叶薯猎人不顾自己宠物的安全，把它们送入危险的地方搜寻蓝叶薯。$B$B我们决不能宽恕这样的行为，但是为了保证顾客对我们售出的每一只地鼠满意，我们郑重承诺:所有购买本公司产品的顾客都可以拿着购买凭证随时领取新的地鼠。$B$B祝您狩猎愉快!') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (1276, '引用$B$B「你想要了解更多关于地精工程学的东西?那就问问我们最优秀、最聪明的工程师吧─我想他的名字应该是努比·斯塔普芬格斯。想要知道他为什么叫这个名字吗?这就是地精工程学!」-- 林格·特拉格迪克，地精工程师$B$B「如果你想要知道什么就直说，但是我会告诉你:我们有爆裂物!」$B-- 雅兹·尼托斯伯克，地精投弹手') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (1277, '更多引用!$B$B「完成某件超强的发明并亲身感受它的力量，你知道这样的感觉是多么美妙吗?侏儒可不知道。」$B-- 尼克斯·斯普克斯宾，加基森高级工程师$B$B「工程学就是让幻想变得更加奇妙的东西!」$B-- 洛维斯，侏儒发明家') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (1312, '待在一个巨人的胃里给了我一个好好省思的机会。$B$B随着我的身体逐渐变得水晶化，我回想了起我在永歌森林的日子。我那时渴望拥有一个精彩的冒险人生，穿越险恶的国度，渡过浩瀚的大海。我那时太年轻，也太笨了。如果我能逃出这里的话，我将会以务农和雕刻做为我下半辈子的职业!$B$B- 温丹·沙恩') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (1313, '我在想什么?$B$B也许这个问题应该有更好的问法:我坐在巨人的胃里还写什么便笺?$B$B这两个问题都很好，而且我都不能马上回答……$B$B我承认，我来这里并没有什么崇高的目的。我是来找艾萨拉水晶的，这是一种艾萨拉南部特产的水晶。我找到它之后就可以富甲天下了!$B$B不过，看看我现在的样子……') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (1314, '任何一个有智慧的生物找到这张便笺的时候，他们都一定会自问道:「为什么他们会去招惹具有暴力倾向的30尺高的巨人呢?」$B$B-- 穆克') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (1392, '尼尔斯修士:$B$B我的葡萄得救了!$N，也就是这封信的携带者，勇敢地闯入我那满是盗贼的园子，然后带着我的葡萄杀了出来。虽然迪菲亚兄弟会的人依然在河岸上巡逻，但是我所有的收成几乎全都保住了。$B$B你可以在你的商店中再次供应葡萄了。$B$B愿圣光保佑我们，$B- 米莉·奥斯沃斯') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (1432, '比塞克·雷眉$B$B比塞克的游荡将他引入了黑石深渊，山脉的秘密在召唤着他。$B$B愿他的灵魂永远不要踌躇。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (1436, '佩沃尔·铁足$B$B黑暗守卫者佩沃尔是我们最为尊重的侍徒。他携带黑暗之钥的时间远远超过其他黑暗守卫者，这使他付出了惊人的代价。$B$B他的牺牲让我们感到惋惜，对他的怀念会一直留在我们心中……自从黑暗占据了他。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (1471, '所罗门镇长:$B$B这封命令的携带者已经被授予暴风城官方代表的资格。您可以让$G他:她;寻找黑龙军团和黑石兽人之间的联系。如果发现了此类证据，请让这个代表把证据带回暴风城，亲自交给我，届时我再酌情派遣部队来协助湖畔镇。$B$B此致，$B$B大领主伯瓦尔·弗塔根') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
