INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (1551, '你好，冒险者，我向你致敬!$B$B我，克林科·古德斯迪尔，需要一些人帮我完成一些艰钜的任务。因为我自己有很多工和工作，因此得由一个足够勇敢的冒险者来找到清单里列出的物品，并把它们交给我，我保证支付丰厚的报酬。$B$B清单将在下几页中列出……') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (1556, '帮我找到这些东西，然后带到加基森来─别忘了还有这个帐本，我会重赏你的。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (1591, '这块铁砧是乔丹·斯迪威尔的财产 - 请不要使用!$B$B- 乔丹') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (1691, '你好，菲诺克!$B$B我在燃烧平原的研究进行得非常顺利。而且我欠了$N很多因为$G他的:她的;大力帮忙!以下是我继续研究所需要的物资:$B$B钢螺钉若干$B17号扳手一个$B12磅重的鸭毛$B一罐你制造的胶水$B$B非常感谢你，菲诺克，下次我们碰面的时候记得提醒我，不要把煤放在你的鞋子里!$B$B- 丁奇') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (1731, '罗德隆的最后一位国王，泰瑞纳斯·米奈希尔二世在此长眠。$B$B他的一生做出了无数伟大的功绩，他的陨落令人扼腕叹息。$B$B         「愿这位父王宽恕其子嗣所做的一切。$B          愿血染的王冠永远被遗失和忘却。」') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (1762, '这些恶魔的铠甲曾经由那个诅咒了我们的生物所穿戴着。一名英勇的兽人战士击败了他，毁灭者玛诺洛斯已不复存在。让这副铠甲时刻提醒我们，我们经历了多少苦难，我们经过了多么艰苦的斗争才夺回了我们的荣誉。$B$B- 索尔，部落大酋长') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (1772, '维姆萨拉克:$B$B我从你的主人奈法利安那里得到直接命令，如果再有任何外来者进入城堡内部的话，你就要受到惩罚。$B$B不要忘记是谁在命令你，爬虫。$B$B黑手之子，刀锋和战争的主人，真正的大酋长。$B$B-  雷德·黑手') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (1794, '当夜色降临时，泰坦为这片大陆起了一个名字:卡林多─「永烁星光之地」。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (1795, '泰坦对他们在这片大陆上建立的秩序感到满意，于是决定启程离开艾泽拉斯。在他们动身之前，泰坦们决定赋予这片大陆上最强大的物种以守护卡林多、保卫这里的平衡和谐不被破坏的职责。在那个时代有许多龙族军团。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (1800, '守护着知识和魔法的诺甘农将他巨大力量的一部分赋予蓝龙玛里苟斯，从此玛里苟斯被称为织法者，守护着魔法和神秘的圣殿。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (1840, '这棵巨大的橡树是暗夜精灵与自然和谐关系的永恒象征，它所散发的生命能量可以慢慢地扩散并治愈整个世界的创伤。暗夜精灵将他们的世界之树命名为「诺达希尔」，这在暗夜精灵语中的意思是「苍穹之冠」。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (1848, '精灵贵族─或者说是数百年前艾萨拉女王所说的「奎尔多雷」─最终登上了东方大陆的海岸，这块大陆后来被称为罗德隆大陆。他们计画在这里建立他们自己的魔法王国─奎尔萨拉斯，并废除暗夜精灵对月亮女神的信仰和夜间活动的习惯。从此之后，他们的身份就变成了「精灵贵族」。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (1854, '达斯雷玛领导的高等精灵离开了卡林多并成功穿越了波涛汹涌的大漩涡。他们的船队在这破碎的世界中徘徊了许多年，在旅行中发现了无数神奇的奥秘与失落的国度。达斯雷玛为自己取了个「逐日者」的称号，不懈地寻找着一个蕴藏着大量魔法能量的地方来为他的子民建造一个新的家园。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (1936, '时光飞逝，艾格文在一处与世隔绝的森林里生下了她的儿子。他被取名为麦迪文，在高等精灵的语言中，这个词的意思是「保守秘密的人」。 艾格文相信她的儿子将成长为下一个守卫者。然而不幸的是，萨格拉斯恶毒的灵魂隐藏在她的体内，并且早在她怀孕的时候就占据了她的孩子的躯体。艾格文根本没有想到，刚刚来到这个世界的新的守卫者已经被他最大的敌人占据了。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2019, '尽管如此，在联盟的侦察员毫无察觉的情况下，一股强大的兽人势力仍然控制着卡兹莫丹北部的荒野。龙喉氏族的酋长─臭名昭着的术士耐克鲁斯利用一个被称为「恶魔之魂」的远古神器控制着红龙女王雅立史卓莎和她的红龙军团。由于控制着红龙女王，耐克鲁斯在被遗弃的蛮锤要塞格瑞姆巴托中建立起一支秘密的部队。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2057, '科尔苏加德领导的教徒急切地希望死去并为他们的主人服务，他们希望通过这种方式变成不死之身。随着瘟疫逐渐扩散，罗德隆北部出现了越来越多的僵尸，科尔苏加德管理着这支日益庞大的部队，并称他们为「天谴军团」─不久之后，它就会踏进罗德隆的大门，并把人类从这个世界上永远抹掉。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2131, '向你致敬，战士。我不会再奉承你的力量与勇猛，这都是些陈年旧帐了。最近你杀了多少人?我猜没多少。你正在退步，你正在因为缺乏挑战而变得越来越弱。$B$B我可不能让一个战士就这么变成废物，不会管别人是怎么奉承你的，现在的事实就是:你需要接受训练，而我可以训练你。什么时候你那榆木脑袋开窍了，就来找我吧，我在大兽穴外的帐篷下面。$B$B- 弗朗恩，战士训练师') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2152, '海军上将巴瑞恩·西风$B血色十字军舰队指挥官$B库尔提拉斯的公民$B失踪于北裂境的冰封海岸') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2172, '费伦·玛库斯血色修道院的高阶修士 $B斯坦索姆的市民$B在第一次血色修道院防御战中牺牲') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2173, '菲尔拉蕾·迅箭$B血色十字军游侠队长$B奎尔萨拉斯的公民$B失踪于银松森林') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2175, '独臂因瓦尔$B血色十字军的首席刺客$B达拉然的公民$B失踪于北裂境海岸') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2176, '激流堡的奥玛尔$B血色十字军的首任将领$B激流堡的公民$B失踪于寒冰皇冠。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2178, '亚娜·血矛$B血色十字军的第二刺客 $B达拉然的公民$B失踪于提里斯法林地') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2217, '纪念我永远深爱着的杰茜·莫拉雷斯') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2232, 'A:$B$B我们必须不惜一切代价地保持计画的秘密性!如果其他的牛头人部族知道我们之间的联系的话，那后果将会是灾难性的。$B$B- E') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2233, 'A:$B$B只要团结起来，我们的力量会比所有牛头人部族联合起来都要强大!但是，我们需要你的完全服从。记住这一点:只有当我们的计画大功告成的时候，你和你的同胞才会得到奖励!$B$B- R') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2234, 'A:$B$B我们从罗德隆派来的使者不久之后就会与你会面。一旦我们找到了进行会谈的合适地点，就会及时通知你。$B$B- G') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2271, '纳塔卡，千针石林一切安好。半人马的麻烦还没有解决……它们有时候会发起攻击，但是目前还没有形成真正的威胁。然而，似乎有消息说半人马氏族正在集结。$B$B我们总是会认真考虑那些团结在一起的残忍氏族，比如半人马……我尝试着不去过多考虑这些问题，正如你所知的那样……没有什么东西可以消解它们心中那纯粹的憎恨……即使对于它们的同胞，那种憎恨也是非常强烈的。$B$B- 峭壁看守者长角') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2293, '联盟舰队指挥官$B$B暴风城的朋友') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2294, '玛拉·弗塔根女士$B$B暴风城的高阶牧师$B$B在第一次兽人战争后资助逃往罗德隆的难民。$B$B她是为我们打开未来之门的母亲，愿她在圣光中安息。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2295, '在记忆之年代前，温柔的大地之母呼出金色的黎明之雾。当琥珀色的云朵沉降之后，大地上到处都是长满燕麦和大麦的田地。这是她工作的基础─孕育着生命和希望的摇篮。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2296, '大地之母的眼睛，注视着她用呼吸创造的世界。她的右眼，安希(太阳)，给予这片土地温暖和光明。她的左眼，姆莎(月亮)，给予那些躁动不安的生物以和平与睡眠。这就是双眼的力量，每隔半天，大地之母就会闭起一只眼睛。就这样，她为这个初生的世界不断进行着日夜的更替。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2297, '当大地之母的右眼扫过金色的黎明时，她轻柔的手就开始在肥沃的原野上拂动。她的手臂拂过的地方就有高贵的人从土地中出现。舒哈鲁(牛头人)为此向他们挚爱的母亲表示感谢。在充满黎明之光的广袤平原上，大地之母的孩子为她的优雅而祈祷，并发誓永远称颂她的名字，直到世界坠入永恒黑暗的那一天。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2298, '随着大地的孩在黎明平原上行走，他们听到了来自大地中心的黑暗低语。 它向那些孩子灌输征伐的思想和欺骗别人的方法。许多舒哈鲁因此堕入黑暗，并开始变得邪恶。他们抛弃了自己的兄弟，无知地穿行在原野上。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2299, '大地之母的心，因为孩子们的堕落而变得沉重，她已经无法再眼睁睁地看着他们变得堕落。在悲伤之中，她摘下了自己的双眼，将它们放在星空中任其飞翔，安希和姆莎为了抚平彼此的悲伤，只能横穿天空而互相追逐。随着时光的流逝，这两个双胞胎永远互相追逐着。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2300, '虽然已经无法视物，但大地之母不会远离心灵的世界。她用她的耳朵聆听风声，聆听一切穿越黎明平原的东西。她伟大的心还是和她的孩子在一起，她爱的智慧永远不会离弃他们。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2301, '大地之母不仅把勇敢的心赋予她的孩子们，她还将热爱狩猎的精神赐予他们。第一黎明纪元中诞生的生物是野蛮而又狂暴的，它们躲避着大地之母，在阴暗的野外寻找自己的栖身之地。舒哈鲁狩猎这些野兽，并以大地之母的祝福来驯化它们。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2302, '然而，一个强大的灵魂却一直在躲避着他们。英勇的雄鹿阿帕罗(被暗夜精灵称为玛洛恩)长着白色的皮毛，它的鹿角划破天穹，它强有力的蹄子踏破世界的深渊。舒哈鲁猎捕阿帕罗，直到黎明世界的角落，并撒网捕捉那头骄傲的雄鹿。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2303, '为了逃脱，伟大的雄鹿跃向空中。他的逃脱本应非常顺利，但是他的鹿角却挂住了天上的星星。虽然他不断蹬踢挣扎，但是阿帕罗却无法从天堂中挣脱。此时正在追逐安希的姆莎发现了他，她看到万能的雄鹿在奋力挣扎，并对他一见锺情。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2308, '随着黎明薄雾的消散以及岁月的流逝，半神塞纳留斯自行进入了世界的田野中。舒哈鲁(牛头人)对于他的离去感到无比悲伤，并忘却了他教给他们的德鲁伊之道。一代又一代，他们渐渐地忘却了如何与树木以及这块土地上的生灵进行交流。地底深处的黑暗低语再次出现在他们的耳边。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2309, '虽然大地的孩子对于邪恶的密语不再听从，但是一个邪恶的诅咒降落在他们游荡的部族头上。在黑色土地的西边有一群凶恶的生物─半人马。残忍而野蛮的半人马如瘟疫一般蜂拥而至，虽然舒哈鲁在大地之母的祝福下勇敢地战斗，但是他们无法打败半人马。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2371, '达隆郡年记$B$B达隆郡是个座落于罗德隆南部山麓中的村庄，村名是以西面的达隆米尔湖来命名的。镇中的居民朴实而又勤劳，达隆郡在罗德隆历史上一直都是默默无闻的，直到第二次恶魔战争的开始。$B$B在战斗期间，无数英雄从这里诞生并陨落。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2374, '防守部队的力量被不断削弱，但是白银之手骑士团不断支援他们。骑士团的领袖达维·克罗弗德是达隆郡的当地人，他在得知小镇即将遭到攻击时带领他的追随者来到了镇中，与卫队合力抵抗霍古斯的部队。$B$B当霍古斯自己也加入战斗之后，他与达维正面交锋了。他们的战斗持续了很久，最终达维获胜，但是他受了重伤，在击败食尸鬼之王后不久死去了。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2377, '达隆郡年记$B$B达隆郡是个座落于罗德隆南部山麓中的村庄，村名是以西面的达隆米尔湖来命名的。镇中的居民朴实而又勤劳，达隆郡在罗德隆历史上一直都是默默无闻的，直到第二次恶魔战争的开始。$B$B在战斗期间，无数英雄从这里诞生并陨落。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2380, '防守部队的力量被不断削弱，但是白银之手骑士团不断支援他们。骑士团的领袖达维·克罗弗德是达隆郡的当地人，他在得知小镇即将遭到攻击时带领他的追随者来到了镇中，与卫队合力抵抗霍古斯的部队。$B$B当霍古斯自己也加入战斗之后，他与达维正面交锋了。他们的战斗持续了很久，最终达维获胜，但是他受了重伤，在击败食尸鬼之王后不久死去了。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2438, '你好，我的$G兄弟:姐妹;。破碎之手氏族向你致意，并希望你在山谷中找到一个合适的接头人。现在是对你进行考验的时候了，所以，别以为没有人监视你。$B$B我的职责是代表破碎之手评估你的技能，然后告诉他们你是否已经准备接受更大的挑战了。$B$B当你准备好了之后，就到大兽穴最深处来找我，我会在那里等你的。$B$B- 鲁瓦格，潜行者训练师') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2440, '注意:$B你必须立即向斯兰·库尔曼报到。他在A3区中，也就是当地居民所说的安威玛那里。在与库尔曼接头之后，你要着手准备参加即将来临的战斗─夺回我们的家园诺姆瑞根!$B$B我们所有的努力都是为了这个最终的目的。在完成此任务之后，新的任务会很快下达给你。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2442, '以麦格尼的胡须之名，我们有很多东西要谈，但是时间有些紧迫，$N。尽快到寒脊山脚下的安威玛来找我，我们要马上开始。$B$B我可以告诉你一大堆事情，但是那些对我们都没有用……特别是对现在的我们来说。我们当前需要关注的东西很简单:如何抓紧一把斧头，我们护甲的重量，以及我们在战斗时所流的汗滴的味道。我们就从这些开始吧。$B$B- 斯兰·库尔曼，战士训练师') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2450, '注意:$B$B保持安静!不要四处张望!也许有人正在盯着你。$B$B我的名字叫做阿拉玛尔·格里姆，$N。我可以训练那些追寻真正的知识和力量的人。 上级授意我与你进行秘密的联系，然后向你传授真正的魔法。$B$B如果可以的话，就到安威玛的后方来找我。$B$B- 阿拉玛尔·格里姆，术士训练师') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2462, '你好，我的$G兄弟:姐妹;。自然的精灵告诉我，你已经做好协助我们盟友的准备了。你和元素有很深的联系，当你开始我的课程之后，你就变得越来越强大了。$B$B现在我要派你去见试炼谷的萨满训练师，兽人史克里克。她已经知道你会去找她接受训练了。让我们的祖先为你而感到光荣吧。在我们再次见面之前，愿你一路顺风。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2465, '你和世界的联系，世界和你的联系，这些对一个成功的牧师来说都是非常重要的。智慧与怜悯将会让你帮助那些真正需要帮助的弱者，过于急躁和慌张的决定都会使其他人无法变得更加强壮，甚至会伤害他们。$B$B当你开始懂得以上这些话的意思时，你就需要学习新的技能和法术了。这时，就到北郡修道院的图书馆里来找我吧。$B$B- 安妮塔，牧师训练师') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2466, '有着圣光的支持和每天都有的新发现，现在你应该为自己是铁炉堡的$G儿子:女儿;而感到自豪了。探险者协会每天都在为那古老的问题找寻失落的答案，现在满怀信仰的你也加入了我们的行列，与石腭怪以及其他一切胆敢威胁我们领土的邪恶力量进行战斗。$B$B等你有空了就来找我吧，我在山脚下的安威玛。$B$B- 布兰斯托克·卡德尔，牧师训练师') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2467, '为你的灵魂未被放逐到扭曲虚空中而感到庆幸吧，$N。为你能值得我花时间亲自书写这个卷轴感到由衷的庆幸吧。$B$B你所认识的人，以及你曾经关心过的人，都已经不再存在了!你必须学会如何以你现在的状态「活」下去，我建议你首先学会这件事情。$B$B如果你准备迎接试炼的话，那就到丧钟镇的教堂里来找我。$B$B- 黑暗教士杜斯滕，教士训练师') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2490, '我希望我的符印可以顺利地寄到你手上，$N。森林之魂告诉我你即将到来，所以我立即寄出了这封信。我希望可以与你分享我的经验，并为你将要在泰达希尔接受的各种重要使命做好准备。$B$B过去的几年中发生了许多事情，我们要做很多事情来帮助艾泽拉斯世界的其他种族。当你准备好了之后，就到奥达希尔来找我，我会在树屋的第二层等着你。$B$B- 珊达，牧师训练师') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2512, '奥斯瑞克:$B$B以下是我们所需要的护甲列表:$B$B10件锁甲衬衣$B20顶头盔$B30块护甲片$B15双锁甲靴$B$B我们总是欠你的情。一旦西部荒野不再受到盗贼的威胁，我就可以请你来我家里做客，这样也能让我心里好过一些，这个地区的菜肴以前可是远近闻名的。$B$B- 路易斯$B军需官，哨兵岭') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2531, '这三页的文件是空白的。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2611, '……那就是你可以找到血色大领主之剑的地方，灰烬使者。$B$B是不是很惊讶?') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2632, '<你看不懂这些书页上的文字。>') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2636, '<你刚刚瞥了这些书页一眼，就感受到了一阵灼热的疼痛。>') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2637, '……如果可以的话，躲在窗台或桥墩底下。找一面坚固的墙也是安全的办法。$B$B<更多模糊的文字。>$B$B在五到十五……之间，使用……治疗。$B$B<更多模糊的文字。>$B$B在成功的袭击之后，好好休息接受胜利。待确实过了十至十五秒后，前往城里展示你的……让人们观看崇敬。$B$B<瞄了一眼其余的文字概要后让你头疼不已。>') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2653, '<你刚刚瞥了这些书页一眼，就感受到了一阵灼热的疼痛。>') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2654, '<HTML><BODY><H1 align="center">军阶概述</H1><BR/><BR/><IMG src="Interface\\PvPRankBadges\\PvPRankAlliance" align="left"/><BR/><P align="right">What follows are</P><P align="right">the military ranks</P><P align="right">of the Alliance,</P><P align="right">proceeded by such</P><P align="right">information as is</P><P align="right">known for the races</P><P align="right">of the Horde. Each</P><P align="right">is presented in two</P><P align="right">sections, the officers and then the enlisted, with the ranks of each listed in descending order from highest to lowest. Long live the Alliance!</P></BODY></HTML>') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
