INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2659, '当你凝视着眼珠时，脑海中便浮现出战争的场景。$B$B似乎这场可怕的冲突发生在罗德隆的某处。$B$B在尸横遍野的战场上，隐约可见一名女性，独自与浩如烟海的天谴军团作战。她显得那么绝望无助。$B$B从她手中施放的光芒瞬间便砍杀数百名不死生物。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2660, '<HTML><BODY><H1 align ="center"> HORDE排名</H1><BR/><IMG src ="InterfacePvPRankBadgesPvPRank01"/><BR/><P align ="right">第一中士</P><BR/><BR/><IMG src ="InterfacePvPRankBadgesPvPRank04"/><BR/><P align ="right">高级警长</P><BR/><BR/><IMG src ="InterfacePvPRankBadgesPvPRank03"/><BR/><P align ="right">警长</P><BR/><BR/><IMG src ="InterfacePvPRankBadgesPvPRank02"/><BR/><P align ="right "> Grunt </P><BR/><BR/><IMG src ="InterfacePvPRankBadgesPvPRank01"/><BR/><P align ="right">侦察员</P><BR/><BR/>< / BODY></HTML>\t') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
