INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2666, '一切似乎都是徒劳。很快女祭司周围就堆满了农夫的尸体……倒下的尸体又站起来了。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2672, '疯狂的克林弗兰:$B$B克林弗兰在燃烧平原上游荡。谨慎地接近他，迫使他现出原形。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2675, '猎人，你要多加小心，那些恶魔都不会贸然行事。如果它们觉得自己没有绝对的胜算，就会选择逃跑。$B$B你一定要独自行动。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2676, '<HTML><BODY><H1 align="center">联盟军阶') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2677, '<HTML><BODY><BR/><BR/><P align="left">长眠于此的是霜狼氏族的第一任酋长，我们敬仰的部落酋长索尔的父亲 - 杜洛坦。他被那些想要让我们永远受到奴役的同胞背叛。杜洛坦为了我们的自由而献出了自己的生命，我们敬仰他，以及他留给我们的珍贵遗产，他伟大的儿子。</P><BR/><P align="left">德雷克塔尔，霜狼氏族的先知</P></BODY></HTML>') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2695, '为了引导出仪式所需的能量，铃铛、车轮和蜡烛都具备独有的属性。$B$B达斯莫拉的铃铛，一旦铃响，可赋予术士活力和能量的法阵。$B$B黑暗战车之轮，一旦旋转，可保护法阵中的人物免受伤害。$B$B末日蜡烛，一旦燃烧，可对进入法阵的敌人造成可怕的伤害。$B$B因此在仪式中保持三种物品的正常运作是至关重要的。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2731, '<HTML><BODY><P align="left">长眠于此的是霜狼氏族的第一任酋长，我们敬仰的部落酋长索尔的父亲 - 杜洛坦。他被那些想要让我们永远受到奴役的同胞背叛。杜洛坦为了我们的自由而献出了自己的生命，我们敬仰他，以及他留给我们的珍贵遗产，他伟大的儿子。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2770, '<HTML><BODY><BR/><BR/><P align="left">长眠于此的是霜狼氏族的第一任酋长，我们敬仰的部落酋长索尔的父亲 - 杜洛坦。他被那些想要让我们永远受到奴役的同胞背叛。杜洛坦为了我们的自由而献出了自己的生命，我们敬仰他，以及他留给我们的珍贵遗产，他伟大的儿子。</P><BR/><P align="left">德雷克塔尔，霜狼氏族的先知</P></BODY></HTML>') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2779, '霜狼洋葱:雷矛的光荣事迹$B:范达尔·雷矛着$B$B霜狼是什么?答案很简单:霜狼就是那些企图摧毁我们伟大的帝国的野蛮人。$B$B霜狼跟洋葱非常相似，霜狼设立了层层防御力量;一旦外层被剥离，就会露出嫩心，这样我们便可以就着蒜汁食用了。$B$B太美味了!') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2785, '我们请求你，赞达拉的赞札。$B$B祝福那些请求你的帮助的人吧，赞札。祝福那些跟赞达拉人民结盟的人。$B$B在这关键时刻帮助我们。赐予我们力量，打败敌人，再次消灭哈卡。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2787, '他的名字为黑暗的艾泽拉斯带来了光明。$B$B他的勇气推翻了痛苦的高墙。$B$B白银之手将继承骑士的事业，为世界造福。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2789, '这位神圣的骑士的悲剧$B$B不会因他的逝去而终结。$B$B我们尊敬他，感谢他!$B$B乌瑟永远代表着荣耀和光明!') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2794, '一支古老，敏锐的种族－－其拉，想要争夺卡林多大陆的统治权。而自负、专制的鹿盔和他的暗夜精灵军队正式与牠们展开了激战。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2797, '抱着无畏及坚定的决心，想复仇的范达尔·鹿盔继续计画着一切。希利苏斯的战败会导致暗夜精灵种族重大的损失，甚至可能会失去整个世界。$B$B战火延烧了好几个月。整个希利苏斯都被其拉军侵袭了。鹿盔和他的军队被逼回塔纳利斯。在大批军队被毁灭和无数无辜生命被屠杀之后，范达尔·鹿盔一直以来的自负被彻底地熄灭了。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2798, '他的骄傲被完全地粉碎，这是鹿盔第二次在人生中感到彻底的恐惧。于是，在塔纳利斯，鹿盔找到了安纳克罗斯－－诺兹多姆之子，并请求青铜龙军团的协助。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2799, '一开始，安纳克罗斯拒绝让青铜龙军团卷入低等种族的事务之中。直到其拉莽撞地攻击了时光之穴，安纳克罗斯才同意加入暗夜精灵的军队。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2800, '安纳克罗斯很快的了解到即使是强大的青铜龙军团也无法阻挠其拉军队的入侵。每当他一口气杀掉五十只虫兵，就会有一百只等着替补牠们的位置。随着暗夜精灵阵线越来越衰弱，这个威胁将会蔓延至更北方的菲拉斯荒野的迹象就越来越清楚的浮现，安纳克罗斯决定是时候该让守护巨龙之子们都意识到这个情况。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2810, '暮光之锤紧急通告:$B$B寻找背叛者奥泰尔的过程进展的相当顺利。我们的斥候已缩小范围到西部荒野的洞穴群。$B$B奥泰尔的背叛不能被原谅，而他的逃脱显示了我们组织的安全性有极大的漏洞。$B$B任何被发现藏有奥泰尔消息的人，将会受到适当的处分。$B$B- 暮光领主艾沃兰') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2812, '暮光之锤紧急通告:$B$B以下资讯描述和我们的深渊议会的主人们沟通的风石之使用方法。$B$B任何对风石没有意义的使用都将被处以最严厉的惩罚。$B$B- 暮光守卫者哈弗斯') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2815, '高阶深渊议会的首领$B$B只有暮光领主能与斯卡德诺克斯王子、大元帅维拉希斯、卡苏姆男爵或斯古恩领主联系。$B$B不论在任何情况下，任何暮光之锤的低阶成员都不能与高阶议会建立联系。若发现任何外来人员使用风石，他将立即被化为灰烬。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2817, '教派的现状，第127卷$B$B这真是一个令人高兴的一天!我们在希利苏斯接受特训，而且最终通过了这次特训!$B$B报告说我们最北面营地的毁灭将会挑战不忠实者之心，但是这次屠杀不会被视为一次悲剧。决不!') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2818, '被一名高阶深渊议会的成员溅洒我们的鲜血，这是一种无上的祝福!我们必须羡慕我们倒下的朋友，他们的灵魂正安息在一头最荣耀的野兽的胃中!$B$B赞美上古诸神!赞美他们的仆人!赞美暮光之锤!') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2825, '凯兰海军上将之墓\r\n\r\n从来没有一位海军上将如此勇敢，他以尊重、尊严和荣誉的态度领导着他的部下。\r\n\r\n库尔提拉斯王国在哭泣，他勇敢的船员们也在哭泣。\r\n\r\n  舰队永远不会忘记你。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2829, '亲爱的日记，$B$B今天，我的头号敌人 - 纳里安·柔想，企图派他的密友在他处以死刑的场地欺骗我。他的死刑。你相信吗?$B$B我历经千辛万苦才想出这个恶魔般的计画，要把他从那个该死的茅屋里引诱出来而他却这样做?算了……我太生气，不想写了。下次再说。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2830, '亲爱的日记，$B$B我在愤怒中离开了藏身之处。我真的很生气。我决定重新设计奴仆们的制服以反映我的不安。我现在觉得好多了但是有个东西不见了。我马上就回来……') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2833, '亲爱的日记，$B$B我一定是老了。我完全忘记我跟你说了纳里安和他的诡计的事。总之，当我看到扮成纳里安的诱饵，我真的很生气所以就命令二号把那个笨蛋给杀了!$B$B我进入飞行器里开始撕毁他宝贵、愚蠢、无知的龙语书。真是爱炫耀!谁会读龙语啊?我真是痛恨他!') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2834, '亲爱的日记，$B$B抱歉，我睡着了。然后我就一边愤怒的开着飞行器，一边把那愚蠢的书一章章丢出去。我看到我下方的暗语峡谷里有个恶魔，便决定要将第一章变成魔法的纸龙卷风，把它的身体碎成好几百万片!这是解放。魔法 + 纸张 =乐趣。$B$B这让我非常开心所以我决定飞到东部王国。我的第一站是熔火之心。纳里安总是一直讲那边的事!「…熔火之心怎样怎样，拉格纳罗斯如何如何…」') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2835, '你知道吗?如果他那么喜欢它，或许他会去熔火之心试着把他的书拼凑起来，然后从一堆灰烬中让那些章节再复活过来!哈!$B$B当我还在邻近地区的时候，我发现有一些在维克多·奈法利斯领主实验室的技师可能会用到这个龙语的东西。把炸弹拿开!') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2836, '已经开始变成一种运动了。我真的撕这该死的书撕到上瘾了!$B$B接下来就简单了。$B$B幽暗城，恶臭腐烂死人的家，可能有着我吃过最棒的辣椒，这样是一章。暴风城，起司的首都，另一章。日记，你有把暴风城的起司拿来放在幽暗城的辣椒上过吗?嘿?这应该听起来有点警惕作用。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2840, '享用你在我贵重的收藏品中发现的复仇和怒风装备吧。相信我说的：我很高兴做了我父亲没有做的事……$B$B由衷的敬上，$B$B奈法利斯$B"奈法利安"') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2844, '他那些猎犬来的比老鹰还要快，$B$B然后他吹了声口哨，大吼，依序喊着牠们的名字;「$B$B现在，毛瑟!现在，奇尔顿!现在，乔登跟卡普兰!$B$B上，纳格!上，帕度!上，古德曼跟梅特森!$B$B到门廊的顶端!到墙顶!$B$B现在冲过去!冲过去!冲过去啊」') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2851, '不!当新实验程序开始时，我的主要学徒:泰勒塞翁，突然无预警的在我眼前萎缩，蜷屈成这种状态着实折磨了我的兄弟。我极力想制止，但他就这样离我远远而去。除了让他从苦痛中幸免外，我也没别的选择了。$B$B而这是研究与发明的代价，只不过这代价实在是太沉重了。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2853, '我来迟了。第3个学徒已不知不觉和其他人建立起邪恶的勾当。我必须容忍现状，但当务之急是避免让其他未受影响的学徒同流合污。$B$B我要让所有人都知道我在远行者居所行周期安息日。这样一来，我就可以好好构思解决难题的办法。$B$B我一定要想出正确的判断来弥补这个可怕的错误。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
