INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2870, '<HTML><BODY><H1 align="center">瓦萨拉克，继续……') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2871, '<HTML><BODY><H1 align="center">瓦萨拉克，继续……') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2872, '致所有强壮的男人和女人们:$B$B天谴军团已经回来了而我们务必要将一切琐碎的争吵放在一边，并面对这个威胁。银色黎明会赞赏任何卷起袖子，加入对抗天谴军团威胁的人。$B$B所有要保卫我们家园的人都会聚集在东瘟疫之地的圣光之愿礼拜堂。团结一致，我们就能获得胜利。$B$B名册保管者$B银色黎明') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2878, '我的艾米莉，$B$B几天前，我们闯入了这个被圣光遗忘的地方，听从国王的命令返家。虽然这周围很荒凉但我的心很轻松，因为在前往海岸严寒的长途跋涉和遥远辛劳的航海后我就知道，我会在你的怀中找到安慰。$B$B我们今天到海岸线找我们的船，我们回家的工具，已经是烧黑的外壳;我们无法离开，别无选择，只好往这深不可测的荒地中心走。$B$B我为了保护你已走到了世界的最尽头，艾米莉……而现在……我衷心希望我还和你留在罗德隆。$B$B每当我睁开眼想的都是你。你是我在这冰冷土地上的温暖，亲爱的，而且没有人可以改变这个事实。$B$B麦克斯韦尔') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2880, '鲁宾，$B$B我知道你可能永远都不会看到我写的这封信;只是我不能闲着，听着壁炉谷的墙壁不断发出撞击声。亡灵就在我们的村子外面，不停袭击我们，而我们受到命令要保护镇民直到援军前来。$B$B我的腿在上一次的行动中断了，所以我坐在这里，一无是处，我的剑插在腰间，我们的防御有个裂缝。没有空闲的玩笑……只有打斗和死亡的声音。空气中弥漫着恐惧的味道。$B$B阿萨斯王子在这里，和人们在前线打仗。如果不是他的出现我们很久以前就死了。他对这片土地和人民的热爱是有感染力的;我很荣幸能为他工作，也会一直跟随他直到老死。$B$B战争越演越烈;不管腿有没有断，我都不能坐在这里。我们需要每一个人。我希望你看到这些话的时候情况能乐观些。$B$B你的朋友，$B里格瑞$B$B') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2881, '$B$B海利安娜，$B$B我，瓦古斯，虽然与你的希望相违，不过我还活着。我鄙视自己穿着这可笑的护甲在乡间游荡。$B$B我们的上一个命令要我们前往安多哈尔寻找一些谷类或类似的狗屁东西。为什么这么多地方却偏要我找安多哈尔的食物?从军这整个想法真是有够可笑。$B$B好好安息吧，海利安娜阿姨，我会回去继承你的遗产的;即使我伤的极为严重，又饥又渴，坚定的恨意会驱使我继续向前进。$B$B瓦古斯$B$B') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2882, '最亲爱的亚蜜利亚，$B$B今晚我见到了会终生萦绕在我心中的事。$B$B斯坦索姆战火延烧，我们都要负起责任。$B$B今晚我们的王子带领我们到了城镇的街上;他命令我们闯入民宅然后……在他们熟睡时把他们杀光。阿萨斯主人说，他们得了瘟疫，所以要在他们杀死我们之前把他们杀了。$B$B那简直是大屠杀。几百人寂静地死在曾誓言要保护他们的剑下。我无法再忍受了;我逃了出来。$B$B我或许是个背弃者，但我无法做出那样残暴的事。在每个民宅里，我在受难者死去时看到了你的脸孔，和我们的孩子。如果我这样做是个卖国贼的话，那就是吧。$B$B我希望能及时找到路回到你身边，但路途并不安全。我不在的时候替我传达我的爱给我们的孩子。$B$B詹姆士$B$B') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2883, '珊拉，$B$B我越跟着我们的阿萨斯主人往北走，越北，我的心就越沉重。他虽然曾闪耀着圣光，我现在却感应到一股黑暗的年轻圣骑士灵魂。他的热诚被一股沉思笼罩着，在他的灵魂里有一些我无法理解的梦魇……$B$B我们很快就会着陆在冰冻荒原。虽然阿萨斯手下很多人都因受寒或与腐败的野兽搏斗而病倒，他告诉我们他要在冰地里寻找的东西会扭转战争情势。但我并没有因为他的话感到安慰，因为在他这样说之后……一抹阴森的微笑浮现在他有棱有角的嘴角，那股寒意比任何暴风雪还要让我冷的刺骨。$B$B为我们祷告吧，珊拉，也为我们的世界祷告，$B$B托尔哥$B$B') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2884, '亲爱的帕米拉，$B$B明天我们就要站上安多哈尔的战场了，我怕这将是我写给你的最后一封信了，我的爱。那些亡灵丝毫不见疲累，而我们，只不过是凡人罢了。我们抵挡不了它们。但不管再怎么样烦恼，我们虽说必定会死去，但我们的希望仍然坚定。圣光会战胜一切!$B$B我最亲爱的，虽然那些黑暗的恐怖猛攻我们的墙垣撞击我们的心灵，最后浮现在我脑海的不会是死亡，我很安慰知道这点。我会想念着你，而且我终将体验宁静。$B$B克里斯多夫') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2885, '嗨，$N。经过调查之后，我从那张便笺发现了一些讯息。$B$B关于詹姆士，恐怕，我只能找到一点点。不过我确实找到一些亚蜜利亚家人的事。$B$B虽然她或她的孩子们都没从战争中生还，但她的哥哥还活着，一个叫做亚历山大·考德尔的人; 你可以在铁炉堡荒弃的洞穴找到他，研究着燃烧军团危险的魔法。$B$B她还有一个亲密的表姐，一个叫迪兹·斯诺班的女人，她在奥格玛筹划着阿拉希盆地的战役。$B$B你应该在下次前往那里时去拜访他们其中一人。我相信他们会很乐意听听逝去的亚蜜利亚的事。$B$B') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2886, '你好，$N。我想你一定会对我调查的结果很有兴趣。$B$B事实证明，鲁宾和里格瑞还活着 - 换句话说 - 还有家庭。即使他们已经知道死去的士兵的事，拜访他们其中一人都会是值得的冒险。$B$B你可以在幽暗城的军事区找到鲁宾的前妻，琼安娜·怀特豪尔，她大部分时间都在那里。我不知道她能不能接受这个事实，要小心。$B$B至于里格瑞，他的阿姨成了暴风城的孤儿监护人，是个值得钦佩的职务。$B$B不管你生命中的道路是什么，我希望你的努力都能有好运气。$B$B') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2887, '$N，我希望这封信对你有所帮助。在探究了一阵子之后，我发现了一些消息，关于写下你找到的便笺的那个人。$B$B珊拉的父亲带领着跟随他信念到雷霆崖朝圣的被遗忘者和巨魔。他的名字是麦尔斯·威尔什，你会在预见之池找到他和他的亡灵朋友。$B$B同时，托尔哥是被他的表姐埃丽莎救活的。据我了解她是个很低调的人;她都在达纳苏斯的月神殿里。$B$B我强烈建议你去拜访任何一个人，$N。他们永远都不会了解托尔哥或珊拉的命运的。$B$B') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2888, '保管者将你发现的信给大家传阅了，$N，我想你可能想要了解最新的情况。$B$B最后一位仅存的「瓦古斯」家族成员住在塞纳里奥城堡，希利苏斯的沙漠里。他以卡隆·海金斯的名字自居。$B$B你应该在下次旅行至荒原时和他谈谈。他或许会对我们发现的事情有兴趣。$B$B') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2889, '你好。我终于找到时间仔细研究你在天谴军团发现的公文。虽然花了点时间，但我相信我找到了一名死者的亲戚。$B$B麦克斯韦尔的姐姐，一个叫萨瑞娜·克罗姆温德的女人，在藏宝海湾经营一家小型武器店。我不确定她和她弟弟的关系亲不亲密，但如果你想了解，你就该安排一次会面。这类事情的终止在现今是珍贵且稀有的。$B$B') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2890, '我终于发现一些先前与你打斗的士兵们的消息。线索很难追，因为他们的家谱没有正确的记载所有资讯，但我最后仍找到一个血亲。$B$B你相信圣光之愿礼拜堂的护理者奥林事实上是克里斯多夫的儿子吗?听到父亲的消息他应会比较放心。如果你再次至瘟疫之地为银色黎明服务，拜托你，与他谈谈。这会是件善行。$B$B') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2945, '<HTML>\r\n<身体>\r\n<BR/>\r\n<BR/>\r\n<H1align="center">荆棘谷的青山</H1>\r\n<BR/>\r\n<H3align="center">赫米特·奈辛瓦里</H3>\r\n</正文>\r\n</HTML>') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2949, '在接下来的几年里，暴风城背叛了石匠公会后，埃尔加丁爵士对贵族在王国中的角色感到不满。 他不想再维护他父亲的血统为他在贵族院中赢得的地位。\r\n\r\n但我离题了。 这个故事的目的不是作为政治论文或传记。 这是我在荆棘谷的绿色山丘中狩猎大型动物的经历的记述……') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2956, '在上面的岩石悬崖上，在夕阳的映衬下，我可以辨认出我所见过的最大的猛禽。 我用步枪笨拙地开了一枪，但那只猫坚守阵地。 他再次咆哮，这一次比第一次更响亮，然后消失了。\r\n\r\n我们收拾好行李，庄严地返回营地。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2964, '几周过去了，我们的豹皮和虎皮库存不断增加。 我决定是时候将探险队的注意力转移到新的挑战上：猛龙队。\r\n\r\n人类虽然很感激巴尼尔和我提供的训练，但决定不再使用枪支狩猎。 阿杰克对上弦的弓更加得心应手，而埃尔加丁爵士每次离开营地时都会带着他坚固的十字弓。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2966, '我曾在战场上站在一座高耸的地狱火面前，燃烧军团的军队从四面八方推进。 一群不守规矩的巨魔看起来就像丹莫罗山上的长耳大野兔一样无害。\r\n\r\n我们顺利通过了特卡什遗址，这让巴尼尔松了口气。 队伍继续向西行进，向大海前进，绕过南边的祖尔昆达废墟。 当我们登上公海悬崖时，我们发现了我们的第一架猛禽。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2967, '这头野兽根本没有察觉到我们的存在。 事实上，他从探险队收到的唯一问候就是两眼之间的一颗子弹。\r\n\r\n当阿杰克向我点头表示赞同时，埃尔加丁爵士发出了一声衷心的“欢呼”。 我翻遍了我的背包，寻找我的烟斗，希望能抽一口庆祝性的烟。 巴尼尔开始急忙爬上山坡去取回猛禽的尸体。 我盯着那头倒下的野兽，带着每次大杀戮所伴随的满足感。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2968, '但我无法长时间沉浸在杀戮的荣耀之中。 因为当我把目光转向地平线时，几个剪影出现在山顶上，就在可怜的巴尼尔上方。\r\n\r\n*逃跑，巴尼尔！*我喊道。 阿耶克、埃尔加丁爵士和我向巴尼尔上方和追击的猛禽队发射了一连串的子弹、箭和弩箭。 我们中的一个人在一片混乱中击杀了敌人。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2969, '我们匆忙瞄准的射击足以让巴尼尔逃脱。 巴尼尔嚷嚷着下山，重新加入了队伍。 我们急忙跑进丛林。 一群凶猛的鞭尾猛禽跟踪我们的一举一动。\r\n\r\n猎人现在成了猎物。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (2974, '我们一路狂奔回到了营地，丝毫不敢放慢速度。深夜，我们围着篝火静静地坐在一起，大家心里都明白，我们是被奇异的命运所拯救，这就是狩猎高手活动所带来的风险:我们在和命运玩游戏。然而，我们之中的每一个人都可能会在未来的某一时刻面对命运严峻的考验。我这个老矮人感到高兴的是，这一时刻并非发生在荆棘谷的青山中。$B$B--完--') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (3456, '将物资转移到冰点岩石 09.04 05:31-10:50\r\n\r\n13.04 05:12-09:20 在冬泉谷以北的冰点岩建立基地\r\n\r\n冬泉谷侦察 18.04 20:03-22:14\r\n\r\n飞往冰点岩 03.05 06:04-') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (10000, '忠于他们的天性，地精一直在寻找能让他们获利的文物和遗物。正是因为贪婪，风险投资贸易公司派遣了一组地精前往石爪山脉深处。据说，一个神秘的人向他们出售了一个关于一个绝不能被打开的坟墓的线索，然而这个坟墓也同时提供了迅速积累财富的方法。\n\n如果不是地精，其他人可能会立刻逃跑，不吭声，然而当涉及到金子时，地精很容易被说服。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (10001, '事实证明，他们的任务是艰巨的，许多人只能在这些山脉中死去，要么死在野蛮的野生动物、守卫坟墓的暗夜精灵手中，要么死于他们自己的创造物。\n\n随着他们缓慢地前进，一些人屈服于恐惧，坟墓里有一些黑暗的东西。对于其中一些人来说，不值得为别人的金子而浪费自己的生命，所以他们中的一群人带着他们所能凑齐的一点点资源飞往杜隆塔尔。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (10002, '<你的新朋友看起来有点脱水。>') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (10010, '在前工头纳特·布拉斯滕托姆的带领下，叛逆的地精在剃刀岭附近坠毁了他们的飞机。 正是在那里，纳特结识了一位熟人，他们的计划中将会用到这个熟人，以躲避部落的旗帜下。\n\n当地的厨师是纳特过去在棘齿城遇到的人，当时纳特只是一个试图出售兽人假冒商品的卑微商人。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (10011, '在跟随他的少数地精的努力下，纳特猎杀了当地的野猪，他向守卫提供恶作剧的贿赂，允许他们通过他们的土地。\n\n感谢他的雇员艾格尼丝有一袋非常特别的香料，兽人厨师成功地将一顿简单的饭菜变成了一场盛宴。\n\n地精贿赂当地守卫的阴谋成功后，他们被允许安全通过部落的土地，并得到他们有可能享受的保护。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (10020, '纳特知道他必须向部落证明他和他的前雇员有能力为这项事业提供帮助，因此他前往棘齿城与加兹鲁维会面。 加兹鲁维在部落内部有联系，他将是纳特用来对付那些可能会因为风险探险公司的声誉而放逐他们，甚至在最糟糕的情况下杀死他们的人的一张重要牌。\n\n加兹鲁维一开始并不同意。 他需要几天的时间来考虑是否要帮助这些难民。 最后他得出的结论是部落缺乏地精的接触，并呼吁纳特向他提出组建一个联盟的提议，任何决定加入部落的地精都可以加入。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (10021, '纳特对此感到困惑，但他看到了一个巨大的机会，决定跟随这个计划。于是，一个新的联盟诞生了，以杜隆塔尔劳工联盟的名义，这个新的地精团体将接纳来自世界各地希望加入部落的地精。\n\n作为杜隆塔尔劳工联盟的大任务大师，纳特很快将有机会向部落证明他的人民的价值。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (10030, '随着杜隆塔尔劳工联盟的成立，加兹鲁维在部落酋长面前为他们作证，纳特所要做的就是等待任务。他在杜隆塔尔留下了一些人，协助满足各种需求，而其他人则被派遣到卡利姆多各地提高声誉。至于他和一个小团队，他们将在尘泥沼泽定居，建立起一个名为“泥链镇”的新部落定居点。\n\n在接下来的几个月里，地精们不得不适应严酷的环境，他们不仅受到当地野生动物的攻击，甚至还不得不精心制作工具来击退奥妮克希亚的产卵。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (10031, '最终，在耐心等待之后，大酋长下令杜隆塔尔劳工联盟在部落首都奥格瑞玛附近建立一个港口。这个港口需要付出巨大的努力，但要不是在刃拳海湾附近的石油资源，它们可能需要更长的时间。\n\n经过长时间的投入和辛勤的劳动，这个港口很快就成为了地精的主要城市。纳特将其命名为“火花港”，借此将他和杜隆塔尔劳工联盟的名字铭刻在了部落的历史中。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (10032, '由于暴风城财政部最近出台的过度限制措施，贝壳公司被迫将办公室迁至自由贸易港——藏宝海湾。如果你对此事感到不满，请向暴风城要塞那些目光短浅的官僚发泄你的不满，是他们密谋阻止你获得应有的财富！') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50065, '教授告诉我，他已经教会了其他人如何伪装自己。他没有告诉我他们在哪里，但他给了我一张清单，上面列出了他们的伪装，我必须去那些他们成功渗透过的地方寻找他们，他们可能也想教我。$B$B¡¤ 亡命劫匪（Defias Footpad）$B$B¡¤ 黑铁矮人（Dark Iron Dwarf）$B$B¡¤南海海盗（Southsea Pirate）$B$B¡¤ 达拉然巫师（Dalaran Wizard）$B$B¡¤ 石拳穴居人（Stonesplinter Trogg）$B$B¡¤ 辛迪加高级成员') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50066, '红色按钮！当然是启动引擎！操纵杆用来控制方向。\n\n当然，在途中不要撞到岩石。撞击地标可以得分，也可以将这些侏儒撞落！\n\n如果你不幸经历了赛车爆炸，而且没有保险，你的财物将被传递给克鲁扎克和地精工程团队。\n\n感谢你为我们进行赛车耐久性碰撞测试！\n\n你真棒！') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50067, '红色按钮！当然是启动引擎！操纵杆用来控制方向。\n\n当然，在途中不要撞到岩石。撞击地标可以得分，也可以将这些地精撞倒！\n\n如果你不幸经历了赛车爆炸，而且没有保险，你的财物将被传递给加里·碰撞和侏儒工程团队。\n\n感谢你为我们进行赛车耐久性碰撞测试！\n\n你真棒！') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50080, '闪光平原 — 沙漠生物和沙尘暴的声音已被替代。蝎子人的叮当声不再存在，它们被引擎的强大轰鸣声赶出了它们的自然栖息地。作为来自世界各地的工程师聚集在一起，旨在创造出有史以来在这些曾经广袤平原上奔驰的最快的机器，加基兹坦时报得到了与一些维修人员交谈的独特机会。\n\n"我们在这里试图实现的不仅仅是陆地速度记录。" 格雷戈·菲兹乌兹对加吉兹坦时报表示，他是伟大的布拉斯博尔兄弟的助手，"我是说，当然，我们希望建造出一件被历史铭记的美妙侏儒工程作品，但更重要的是，我们想要击败那些地精！"') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50081, '的确，侏儒工程师在他们的“赛车”开发方面取得了很大的进展，但在技术上紧随其后的是那些看到赚钱机会的地精。\n\n"侏儒从不制造真正能用的东西，" 地精船员之一艾德·斯普洛克特评论道，"他们花费太多时间去修修补补一些小东西，以至于忘记了他们正在做一个更大的项目。调节内部照明和座椅靠垫的较小部件可能是好主意，但如果那个\'东西\'从未动过，那就是完全浪费时间。"') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50082, '侏儒和地精在闪光平原呆了很长时间，试图建造比对方更好的速度赛车。那么，他们取得了多大的进展呢？\n\n加基兹坦时报试图向布拉斯博尔兄弟之一提出这个问题，但他们出奇地不愿意说话。相反，年轻的菲兹乌兹再次发言：\n\n“好吧。我们已经远离机械陆行鸟了，这是肯定的！” 他笑着说：“还有很多工作要做，但我们觉得已经取得了长足的进步，我们即将取得突破。”') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50083, '他趁此机会向加基兹坦时报展示了从侏儒赛车（机械陆行鸟）中奇妙的进展。\n\n"当然，它看起来像是一个与齐柏林飞艇杂交的水塔，" 他带着紧张的微笑说道，"但它在基本结构上有了重大的变化，这将使它变得更好。"\n\n"条纹会让它跑得更快！"\n\n就目前而言，地精技术似乎没有什么值得惧怕侏儒的。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50085, '血液是红色的，伙计\n巨魔皮肤是蓝色的\n如果你正在读这个\n我对你施了一种咒术') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50086, '狂暴发出红光\n心曲闪耀蓝光\n没有人像你一样\n以你的方式附魔我') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50087, '血液是红色的，伙计，\n赞达拉上空的天空是蓝色的，\n如果这让你心情愉快，\n来体验我的巫毒吧。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50088, '玫瑰是红色的，\n鸢尾花是靛蓝的，\n当我看着你时我只能说\n是塔兹丁戈。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50100, '在你收获之前，你会播种种子并用关爱培育它们。\n\n首先，也许是最容易开始的，将是南瓜。你会需要一些成熟的南瓜中提取出的南瓜种子。几乎每个农民在田间都只收集成熟的南瓜，并提取新长出的种子用于下一次收获。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50101, '第二个将会非常相似，但稍微复杂一些——西瓜。要种植一些西瓜，你同样需要种子，而找到这些种子的地方也非常相似。一些农民专门种植这些甜蜜的巨大浆果，只种植它们。他们并不多，但在整个东部王国都很有名。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50102, '更有趣且绝对是另一种故事的是蘑菇。是的，你也可以种植它们！然而，蘑菇孢子非常特殊且各不相同。你必须寻找那些将一生献给此类研究的人。如果适当地照料，蘑菇会茁壮成长。有时它们会像害虫一样生长，应该尽一切努力避免。务必非常小心。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50500, '致魔导师布罗姆利\n\n您寄给我的魔晶碎片真是令人惊叹。高等精灵引导魔法的方式一直让我深感兴趣，它将有助于达拉然的研究进展。\n\n然而，您寄送它们的目的并非如此。经过对这些魔晶碎片的研究，我发现上面留有一种外来魔法的痕迹，正在逐渐耗尽它们的魔法力量。这几乎可以确定，正如您所想的那样，艾萨拉地区正在发生干预行为。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50501, '虽然我给您带来了好消息，但我也必须传递坏消息。这种外来的魔法是龙类的性质，我们有许多例子和研究，所以我非常确定。在该地区操作的唯一团体将是蓝龙军团。他们为什么要这样做，我无法告诉您，但是这是他们的魔法留在了魔晶碎片上。祝您在解决这个问题时好运，并建议您寻求外部帮助，而不是单独对抗蓝龙军团。\n\n您的朋友，达拉然的大法师安希瑞姆·符文图腾。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50502, '你好，布罗姆利！我派遣了携带这个盒子的人带去了你需要的物资！抱歉耽误了一些时间，你和我们之间有很多危险！再次感谢你为我们提供的魔法帮助，你确实推动了我们的项目发展！\n\n弗拉克斯惠斯克家族前线的吉格诺·弗拉克斯惠斯克。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50503, '致吉格诺：\n\n感谢提供的物资，很高兴听到你和你的侏儒们身体健康，并且在继续推进伟大的科学领域。关于我帮助制作的机器人，我有一些消息。在我访问雷瑟斯圣所的纳迦时，我注意到它就在海岸边。他们似乎没有去碰它，可能是因为机器人发生了故障，停止了运作。希望这个信息对你有所帮助，祝你继续好运。\n\n魔导师布罗姆利，肯瑞托。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50504, '艾萨拉侦察 22.03 04:22-05:55\n\n冬泉谷侦察 01.04 14:33-15:03\n\n艾萨拉蓝龙侦察 06.04 15:22-15:51\n\n侦察冬泉谷以北的冰点岩 07.04 05:22-09:31') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50505, '致便携工程师波弗斯巴克，来自诺莫瑞根。\n\n数月来，我未从您那里收到任何消息，我们的情况越来越不稳定，船员死亡，物资匮乏！由于我自己无法传信，我已请本报告的携带者将此信送给您。我要求知道诺莫瑞根的支援在哪里，为何我们这么长时间都未收到任何消息。\n\n我还想请求尽快提供备用的工程师标识传输器，我们很久以前就在纳迦的袭击中失去了它。\n\n吉格诺·弗拉克斯惠斯克！') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50506, '致弗拉克斯惠斯克前线的吉格诺·弗拉克斯惠斯克。\n\n我很难过地告诉您诺莫瑞根的严峻情况。城市已经毁灭，曾经的一切都不复存在！在穴居人入侵之后，隧道受到了令人难以置信的辐射。\n\n我们的许多同胞仍然留在那里，受到辐射的影响严重，变成了邪恶的麻风侏儒！我们逃离的余部在铁炉堡建立了修补匠镇，那是我们目前的新家。我在信中附上了足够您回家的硬币，尽您所能找到合适的方式，回到修补匠镇。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50507, '给看守圣骑士贾纳托斯：\n\n我和我的同伴在前往东部的途中遭到了落锤圣殿的失落者的袭击。许多人被杀害，我们的供应品被抢走，我设法逃脱，并在一个我建立的营地里勉强存活。我会很快回来，等我休息好了。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50508, '你好，卡尔，很久不见了，我想通过这封信向你确保我还活着，仍然精力充沛。我们已经很久没有见面了，我渴望再次见到你。\n\n离开库尔提拉斯后，舰队在海上停留了相当长的时间。最近我们遭到了袭击，船被摧毁，现在我们暂时驻扎在拉皮迪斯岛，位于荆棘谷海岸。当船修好后，我会回家，并会像过去一样，过来和你打个招呼。\n\n你的哥哥，阿诺德。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50509, '弟弟，我们已经很久没有见面了。我目前被困在一个名为拉皮迪斯的岛屿上，位于荆棘谷的海岸，靠近南海，与舰队中的其他人一起。我们已经把这个地方当作家，修理我们的船已经有一段时间了。\n\n当修好了，我会停下来看你和卡尔。我非常期待那一天，希望你过得不错。\n\n你的哥哥，阿诺德。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50510, '给洛鲁克·林行者\n\n你的怀疑似乎是正确的，似乎有一些可怕的事情隐藏在空气中。那些曾经看起来友好的熊怪现在变得邪恶，一看到就会攻击。\n\n土地本身开始枯萎和消失。大的陨石坑点缀着整个大地，大部分野生生物似乎都陷入了类似于熊怪的狂热状态。我无法见到那个据说是这个地方的守护者，因为这个区域太危险，独自旅行不安全。\n\n这里发生了可怕的事情，必须采取行动。\n\n费兰·强风') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50511, '致范达尔·鹿盔、大德鲁伊\n\n灰谷内存在着腐败现象，野生动物日渐变得更具攻击性，而熊怪也变得更加肆无忌惮。 他们不再是我们在森林里的朋友，并拿起武器对抗任何敢于现身的人。\n\n在他们废弃的村庄里，散布着带有黑暗意图的小玩意儿，岩石上刻有粗糙的符文，他们所沉迷的树液也被污染了。\n\n他们迷失了方向，我们必须找到解决这个问题的方法，以免整个森林都因这种疯狂而消失。\n\n法尔丹·碎月者') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50512, '$N，很高兴听到一位新兵对狩猎艺术充满热情。\n\n尽管在生活中，我们从未将自己视为像矮人或高等精灵那样出色的射手，但我们为自己对荒野的热爱而感到自豪，将动物变成了忠诚的长期伙伴，感受着自然的韵律和呼唤，每一阵风的吹拂，每一声河水的响动都给我们的生活带来了极大的快乐。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50513, '适应自然是我们最伟大、最崇高的目标之一，然而当我们尝试着从不安宁的死亡之后找到出路时，我们再也无法适应自然，似乎是自然需要适应我们。在墓地见我，我会在那里告诉你我过去的经历，并教你一些技巧，帮助你在与巫妖王的战斗中生存下来并报仇。\n\n为了女妖之王，为了被遗忘者。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50514, '伟大的金属之中蕴含着克制与黑暗魔法的力量，这是我们工作的关键。要将这种魔法引导到剑的符文中，需要大量的资源，这对我们的同族来说是丰富充足的。\n\n必须在刀刃的表面上刻上黑暗符文，并将其加热到极高的温度，这些符文必须放置在刀刃的中心位置，以免力量减弱。\n\n附魔皮革必须绑定并包裹在剑柄上，以确保武器本身的魔法效果和平衡。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50515, '这些是真正创造符文之刃所需的第一步技术，如果有人要掌握我们伟大的魔法，那么他们也可以学会这些方法。\n\n对于那些忠诚并希望寻求这种知识的人，他们必须在这个凡人世界上找到我。你可以在深谷中找到我，那里阴影重重，有我的仆人陪伴着我。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50516, '很久以前，高等精灵与我们的人类盟友一起教给我们魔法的秘密。他们告诫我们关于规则，以及魔法可能让人发疯！但不要相信这些。我们不像精灵；我们没有同样的弱点。只要保持正确的方向，你会发现魔法既是一种强大的工具，也是一种武器。\n\n当你准备好的时候，来找我吧，在安威玛里我会等着你！\n\n马瑞克·斯特龙努尔，法师训练师。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50517, '致暴风城的马库斯·乔纳森将军\n\n随着时间的推移，日子变得越来越危险，食物开始变得越来越难找到，我们的队伍数量也比以往任何时候都少。 如果说洛丹伦还有希望的话，那就是那些站在我身边、为自己的信仰而奋斗的勇敢的男男女女们。\n\n作为联盟的领袖，我要求你们士兵们协助洛丹伦的战争。 我需要食物和补给来缓解我们自己集结的困境，这样做，当我们取得胜利时，你将得到丰厚的奖励。\n\n  此致，洛丹伦军团塞拉斯上尉。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50518, '亲爱的洛丹伦塞拉斯船长\n\n我很遗憾地通知你，我无法满足你提出的要求，因为没有可靠的方式来运送物资，或者将人员运送到北方，我也没有权力做出这样的决定。\n\n我建议你和你的亲属撤退到暴风城，以挽救你们的生命，避免毫无意义的死亡。 如果你选择不听从我的建议，我只能给你光明的祝福。\n\n暴风城的马库斯·乔纳森将军。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50519, '<日记本的第一页已被撕掉>。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50520, 'Day 31: 天气恶劣，燃料已经开始在桶内冻结，独自在这种寒冷的天气里工作变得极其艰难！我真希望菲兹尔皮普能尽快回来帮助我。\n\nDay 45: 食品供应开始变得有点紧张，我依然被困在帐篷里，四周风声呼啸，埋在一堆毯子和毛皮下，只希望暴风雪能够停止。\n\nDay 48: 终于是一个晴朗的日子，我有机会清理一下帐篷周围过多的积雪，并且吃了几个星期以来的第一顿热饭，真希望天气能继续保持！') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50521, '第52天：好天气结束了，雪再次下落，而且下得很猛烈！我一直在努力修理飞行机器，但没有成功。即便有三天的阳光，我仍旧不能启动它。但我仍对此保持希望。\n\n第54天：我勇敢地冒着暴风雪，发现飞行器的"\n\n第53天：菲兹皮普你这个混蛋，你到底在哪里？谁能想到，仅仅是一次简单的硬币翻转，会给我带来如此多的麻烦！当我回到“诺莫瑞根”时，你得赔偿我许多东西。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50522, '第59天：嗯，我和斯潘通量电容器的努力几乎没有结果。只有一天的"好天气"，飞行器没有起飞，即使我听到它开始启动了。\n\n第62天：饿，真的很饿，食物几乎用完了，我只能活在屑屑中。这次任务失败了，我已经很久没有从诺莫瑞根那里听到任何消息了。无论如何，明天我会将剩下的燃料放入飞行器中并尝试启动它，希望它能工作！') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50524, '亲爱的麦考伊$B$B，\n我最近在供应上遇到了一些麻烦，从巨魔的攻击到未能收到货物。你送来的那个已经给了我很大的帮助，并已经让事情重新回到了正轨。你应该很快就会收到所有的东西。\n\n“皱眉”威利') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50525, '为了纪念弗罗斯特利，他是部落的冠军、掠夺者和朋友。 他将永远铭记在我们心中。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50526, '"鞭笞之树"上布满了无数不同年代的伤痕。有些伤口还在滴落树液，而有些则是淡淡的、如幽灵般的疤痕。树的肉身上有一个名字被刻入，至今仍然流血："艾瑞尔"。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50527, '强大的老巫婆自兽人抵达杜隆塔尔以来，一直在密切关注着他们，现在他们正处于最薄弱的状态。他们的敌人让这片土地与他们为敌，证明它渴望再次属于我们。\n\n我们的新盟友发誓，如果我们让兽人的目光远离荆棘谷，他将强大的回归。他们的萨满将毫不知情，而我们的仪式将扎根。为了伟大野猪的归来而战斗，甚至为之献身吧！') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50528, '达罗凝视塔\n\n一座历史悠久的瞭望塔，建于巨魔战争前人类部落统一时期的阿拉索帝国时期。 它作为军事哨塔一直屹立不倒，甚至在洛丹伦的旗帜下发挥其作用，但在贵族取代它之后，由于贸易衰退，它陷入了困境，直到第二次世界大战 它曾被部落袭击，后来被用作伏击地点。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50530, '银色先锋\n\n这是一支由圣骑士奥雷里安领导的远征营，他在行动中挥舞着萨弗拉斯，只要他们能杀死天灾军团并遵守不侵犯条约，他们就可以接受部落和联盟，他们在艾泽拉斯完成了对抗天灾军团的任务，包括攻击许多天灾军团的防御工事和控制的领土，比如纳克萨拉马斯的大墓地。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50531, '很遗憾，白银先锋已经解散，但退休的圣骑士奥雷利安已经监督将热切岗哨移交给了另一个名为"十字军"的神圣秩序，以在白银先锋缺席的情况下保护和利用达罗古斯。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50532, '十字军\n\n一个由神职人员、牧师、修道士和圣骑士组成的秩序，在第二次战争期间在联盟国家的领导下作为神圣军事秩序运作。在第一次白银之手秩序分裂，创建银色十字军以及献身狂热的血色十字军分离时解散。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50533, '十字军重新复兴，不再使用"血色"或"银色"等名号，因为我们是先于它们存在的最初秩序，与白银之手并肩而立。面对来自部落的新异端威胁以及横扫整个艾泽拉斯的亡灵和恶魔势力的古老敌人，十字军已经再次在联盟内重新成立。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50534, '哨兵哨塔局势报告\n\n当地的野生动物一直是个麻烦，但我们处理得还不错，海岸线上的泥鳞鱼人可能会给塞拉摩带来麻烦，考虑到我们已经看到的活动。\n\n士气高涨，物资充足。\n\n华莱士·克罗斯上尉。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50535, '北地哨塔局势报告\n\n我们失去了一名队员，另有三人受伤，都是被在北部荒野潜伏的血沼迅猛龙袭击的。\n\n最近我们侦察到了部落的巡逻队，已经在道路更远的地方部署了前哨和岗哨，以提前警告我们。\n\n士气尚可，物资正在减少，我们请求食物。\n\n哈克上尉。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50536, '亲爱的兄弟，\n\n很久没有见面了，我一直想写信给你，但一直没有可靠的途径。\n\n如果你能收到这封信，我要告诉你我过得很好。保卫塞拉摩是非常有意义的，这里已经成为了我的真正家园。我所服务的人们是我见过的最好的人，所以请不要担心，我真的很安全。\n\n听到你的生意取得了成功，我感到非常高兴。我期待着我们能再次见面，像以前一样欢庆。\n\n华莱士·克罗斯。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50537, '粉碎机技术\n\n我一直觉得"粉碎机"这个名字在市场营销上选择得有点差，真的。这些机械装置价值相当于五十个地精劳工，而且它们不一定总是用来粉碎，噢不！它们可以锯、撕、扯、粉碎、磨碎、粉碎、碾压，亲爱的读者，可能性，可能性几乎是无限的。\n\n也许你是一个潜在的投资者。也许你是一个想从那些光荣的吞油怪手身上偷走保险丝以在黑市上出售的骗子。嗨，我不评判。实际上，如果你得到了任何东西，我会亲自付出不菲的价钱......不管怎样，以下是最近的投资者：') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50538, '灰谷，战歌伐木场。看到这个操作的规模是一种令人惊叹的奇迹。而且站在河的另一边看兽人和精灵互相刺伤也挺有趣的。\n\n石爪山脉，风剪峡谷的风险投资公司。是的，这些环保主义者又砍了一片森林。但谁在乎呢，那个山谷本来就丑得像罪恶一样，有了一些工业化的东西看起来好多了。\n\n荆棘谷，纳斯费利湖附近的风险投资公司。让地质学家们辛苦工作，这些机器生物撕裂着灌木丛，以便研究能够继续进行。我听说他们在那里还找到了一些美丽的水晶。\n\n西部荒野？我听说有一个豪华设备被运到了西部荒野的某个地方，但我没有听说它去了哪里，或者谁拥有它。很奇怪，就像消失在空气中一样......') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50539, '采石场\n\n亲爱的读者，就在那时！就在那时，我正在穿越燃烧平原，前往烈焰山顶探望一位同事。让我为你勾勒出画面：太阳高高照耀，土地黑如焦油，燃烧不止，野生动物又丑陋又危险。\n\n突然，轰隆！那是我听过的最大的爆炸声。地面都在脉动，真是让人震惊。自然而然，我必须弄清楚是什么能够造成如此美丽的事物。好吧，在地平线上，我发现了一个深绿色的烟雾柱，从东部山丘的一个采石场升腾而起。味道与我能够比较的任何东西都不同，让我的鼻子皱起，眼睛流泪。我没有走得更近，但我可以看到在采石场的入口处......那些好奇的黑铁矮人正在四处闲逛。他们守卫着周边，用那种奇怪的矮人方言互相喊叫！') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50540, '打听了一下，显然这个地区发生了许多活动，来回穿越崎岖的道路。看来这个采石场不再荒废。问题是：它被用来做什么？那种不可思议的气味似乎是新奇的，那里没有火药。爆炸似乎更加频繁和激烈，不仅仅是为了爆破岩石以获得矿物。有一个勇敢（同样愚蠢）的地精试图与领班巴古尔见面，想弄清楚发生了什么。她从未返回过，但说实话，她指望会发生什么呢？\n\n我所知道的是，有活动的地方就有生产。有生产的地方就有生意。而有了生意，就有金子！虽然我不愿意告诉你这些冒险家们在哪里花费时间和精力，但如果我是你，我会和那里的矮人交流一番，弄清楚发生了什么，也许成为一个早期投资者！或者至少卖掉他们的秘密。卖给我。最理想的情况下。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50541, '飞艇事故\n\n为了节省时间和便利，人们真是愿意忍受不少东西。我可能早就在飞艇运输公司里持有股份。它们是旅行的生命线，让兽人、地精，甚至巨型牛头人在几天之内穿越大陆！任何聪明人都会将这视为一项有价值的投资。\n\n然而，现在我们有了竞争对手。一些新秀们开始将航空旅行延伸至卡加斯！没错，沙漠的尘土和风，是任何飞艇的克星，而这些笨蛋们决定将它作为完美的目的地来运营航线。\n\n不用说，结果并不好看。每一天，我们都会收到报告，说有人的尸体在沙漠的阳光下干枯，从飞艇的甲板上被抛出，因为它们在恶劣的风中疾驰！甚至还有坠毁和爆炸的报告，哦天哪。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50542, '不管怎么说地精工程，到目前为止，我们的飞艇上唯一的死亡事件是由于有人认为他们可以通过跳下来从空中缩短旅程时间，或者偶尔使用一些狡猾的精神控制魔法咒语。当然了，我们对此毫不负责 - 当你同意乘坐飞行器时，在小字里已经明确说明了这一点。\n\n我想我不需要详细解释了。选择乘坐他们的交通工具真是疯狂，还是坚持使用已有的航线。保持安全！保持生命！把你的定制交给我们，而不是他们！') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50543, '<复杂的图表展示了不同的魔法属性与熔岩混合的过程。>\n\n仇熔酿，是上层阶级想要保密的秘密项目的绰号，所有研究这份文件的人必须保守秘密。\n\n泄露这份文件中的机密将会受到在"法律之环"中审判的惩罚。\n\n致你，仇熔化学家。研究这些图表和图示，继续实验。失败-不是-一个选择！！！') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50544, '致新部落大酋长萨尔。\n\n我叫卡方，来自外域，曾在黑石山下征战，与我的亲人交战，但他们已不再是以前的样子了。\n\n黑石氏族和旧部落本身已经腐化，迷失于外部影响，我相信你已经意识到这一点。 为此我正在冒很大的风险将这封信送给您。\n\n我希望向你们的新部落宣誓效忠，并拯救我的同胞。\n\n战争领袖卡方。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50545, '致战斗领袖卡方，\n\n我已经阅读了你的信，并且已经倾听。\n\n部落对于艰辛和逆境并不陌生。我们所有人都不得不像你一样努力奋斗并做出艰难的决定。我们是一个由共同的智慧和荣誉价值观连接的平等团体，为这个充满战火和创伤的世界带来了希望。\n\n如果你真的想向我作为大酋长证明你的忠诚，我需要你做一些事情。\n\n暮光之锤已经开始在你的地区出现，他们对这个世界构成了威胁。为我清除他们，我将知道你的承诺是真实的。\n\n萨尔，部落的大酋长。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50546, '工人守则\n\n在监督者的警惕目光下努力工作，未完成工作将导致被奴役。\n\n只有在巴古尔·黑锤的命令下，一整天的工作才算完成。\n\n监工在这里是为了提高生产力，不要质疑他们。\n') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50547, '任何受伤都需要向一名牧师报告。\n\n与机组长交谈以获取每日指示。\n\n在工作进行中，禁止传递任何形式的信件。\n\n必须始终遵守影炉集团的命令。\n\n') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50548, '火焰之王庇佑我们所有人，这里不能容忍失败。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50549, '沃斯，\n\n我的破坏行动正在发挥作用。日复一日，武器从军械库中消失，没有人察觉。很快，士兵们将用木棍战斗。\n\n我不能再在这里躲藏。只是想到再多待一秒钟，与这些叛徒待在一起，就让我感到恶心。让我和哈兰加入你的部下。很快，我们将会在数量上超过塞拉摩的士兵。然后...\n\n他将会复仇。\n\n考德威尔。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50550, '致尼尔斯兄弟\n\n\n事实证明，您提供的信息对于找到卡弗·莫尔森罪犯并将其绳之以法至关重要。 伊斯顿家族的谋杀案终于以圣光之名得到了报仇。 由于你的行动，西部荒野变得充满了希望。\n\n带着这封信的人也找到了旧西部荒野教堂的钥匙，当这片烂摊子被清理干净，土地恢复原状时，我真心希望你能回来。\n\n署名格雷安·斯托曼特尔。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50551, '这封信面向所有公司决定雇佣的麻风病患者，出于我不敢质疑的原因，因为这一点不会对我的工资产生任何影响。\n\n你们这帮次级工程师应该随时待在管道附近。任何被发现偷懒、失踪，或者如果幸运之神保佑，一根管子断裂，你们所有人都将承受后果！') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50552, '另外，对于任何决定来找我谈工资或合同的白痴，要知道我会把你绑起来，喂给那些可恶的焦炭谷生物。\n\n附言：更加努力工作。我们必须尽快完成这个项目。\n\n附言二：保持警惕，注意部落的活动。\n\n-油工大师希格尔·线引') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50554, '想象一下，不把所有的金子都拖到自己身上，真是太笨了！当然，并不是说我这样做。每个员工都一视同仁，我的工资绝不比你高那么多，别想了！\n\nP.S：在身上戴上炸弹，为了公司的更大利益牺牲自己，将确保你的年薪将带回你的家人。而且，他们也会像其他公民一样得到照顾，给他们两个月的免费医疗券。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50555, '附言二：在阅读完之后将这封信焚毁，。\n\n油工大师希格尔·线引') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50556, '尊重油工大师。\n\n不准偷懒。\n\n尊重油工大师。\n\n不准午餐休息！\n\n尊重油工大师......\n\n工作时不准吸烟或喝酒！\n\n尊重油工大师。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50557, '不要说关于那只霍格哥林的愚蠢笑话！\n\n尊重油工大师。\n\n不要问关于你的工资或合同的问题。\n\n尊重油工大师。\n\n工作事故不存在。\n\n尊重油工大师。\n\n最后的规则：尊重油工大师。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50561, '您是否正在寻找一种投资未来、寻找新的财富获取途径的方法？新时代已经到来，随之而来的是一个为所有那些精明的投资者敞开的大门，他们正在寻找一个进入新世界的机会！\n\n贝壳币是一种迷人、神奇的新货币，它将席卷世界，金子不再是唯一的交易和购买手段，而是一种有价值的奥术货币将取而代之。今天，此刻，是您找到可能从未梦想过的财富的机会。\n\n成为一个早期支持者，今天就购买贝壳币吧！') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50562, '时机已经成熟，新的掠夺和荣耀机会来临！贝壳币，一种革命性的新货币已经问世，一个新时代随之而来。年轻的新鲜血液和精明的投资者现在有了在这个新世界中获得机会的大门敞开。\n\n这种新货币已经在风靡世界，不再只有黄金是交易和购买的唯一手段。取而代之的将是这种神奇的奥术货币。是时候投资了，寻找你从未梦想过的地位和力量。\n\n成为未来的支持者，部落的兄弟姐妹们，购买贝壳币吧！') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50563, '星风指挥官，$B$B我将简要说明。您滥用权力，毫无理由地将年轻的姐妹们送上战场的可耻和草率行为已被报告给女祭司和高级哨兵。 牢记您迄今为止无数个世纪的记录。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50564, '被认为适当的是，您将被解除所有领导职责。返回达纳苏斯接受您的新任务。您的最后指令是通知所有哨兵永远离开森林之歌的神圣之地，并解释您可耻的行为不会对他们造成不良影响。$B$B大德鲁伊范达尔·鹿盔。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50565, '布罗森·铁林，$B$B我不敢妄加猜测您拒绝参加南灰谷战斗的动机。无论是因为懦弱、政治权谋还是背叛，我都不应该去评判您。然而，您不得返回森林之歌、阿斯特兰纳或卡利姆多的任何卡多雷据点。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50566, '其他的德鲁伊们也将在哨兵的保护下离开森林之歌，因为他们在指挥官星风的领导下之前没有提供援助。愿艾露恩赐予您宽恕。$B$B高阶女祭司泰兰德·语风。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50567, '我们今天站在这里，以尊崇他们的牺牲，缅怀他们的无私，他们坚定不移的决心，以及他们坚韧不拔的精神，这一精神体现了吉尔尼斯的核心精髓。$B$B他们对国家和同胞的忠诚无与伦比。然而，他们的牺牲并非徒劳，因为吉尔尼斯比以往任何时候都要强大。这些勇敢的士兵留下了永恒的遗产，这个遗产将继续激励我们并指引我们前行。$B$B我们必须坚定决心，重建并继续前进。我们已经证明了我们的坚韧，我们的意志坚不可摧。吉尔尼斯将会长存。$B$B我感谢您在这些充满挑战的时刻对我的信任。$B$B您的国王 - 吉恩') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50568, '在最初属于阿拉索帝国的七个国家中，吉尔尼斯是那个为了获得独立而付出最艰苦努力的国家。虽然洛丹伦通过其贵族的影响得以确保自己的自由，但吉尔尼斯的人民不得不作出巨大的牺牲来争取他们的独立。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50569, '尽管这些事件的确切日期已经湮没在时间的沙漠中，但吉尔尼斯为能够在其他著名国家（如奥特兰克和库尔提拉斯）之前获得独立而感到非常自豪。吉尔尼斯人民是最早摆脱阿拉索贵族枷锁、享受自主统治的人群之一。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50577, '尽管击败了达拉然，年轻的吉尔尼斯国王并没有能够长时间休息。土地上的各个贵族并不总是忠于国王，有些人反抗了他的统治。然而，加拉隆国王的权力太大，他在他钟爱的将领雷文伍德勋爵的帮助下成功地制服了他们。\n\n在他生命的后期，加拉隆国王将重心放在了改革吉尔尼斯的行政体制上。他引入了许多新法律，帮助了南部地区的贫困人民。在他的统治下，吉尔尼斯变得比以往任何时候都更加强大，他甚至在库尔提拉斯和奥特兰克的兄弟们争取独立的战争中给予了支持。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50578, '然而，悲剧降临，加拉隆国王在43岁时被他曾在几年前支持过的奥特兰克贵族暗杀。这一事件引发了两国之间长达数十年的重大战争，使两个王国都遭受了严重的破坏。吉尔尼斯和奥特兰克之间的战争是人类七大王国历史上最血腥、最残酷的战争之一，对该地区产生了持续数个世纪的深远影响。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50588, '从前，有一位勇敢的吉尔尼斯渔夫，名叫丹纳瓦。他与妻子和儿子一起生活在沿海的海港村庄“海港镇”。然而，有一天，一场可怕的悲剧降临，名为“穆\'古尔”的鱼人从海上入侵吉尔尼斯。丹纳瓦的妻子和儿子在袭击中丧生，只剩下他和女儿相依为命。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50590, '凭借着鱼叉和其他简单工具，丹纳瓦召集尽可能多的渔夫组成民兵。他们一起发起进攻，抵御住了穆\'古尔的入侵。越来越多的人加入了丹纳瓦的民兵队伍，最终，皇家军队得知了入侵的消息，南下与威胁作战。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50591, '皇家军队的援助打破了穆\'古尔的阵线，迫使他们退回海中。但丹纳瓦想要的不仅仅是胜利，他还想为妻子和儿子的死寻求报仇。因此，他召集了渔夫们，发动攻击敌人，带着他们信任的鱼叉登上了他们的渔船。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50592, '凭借着他们熟练的技巧，他们无情地追击穆\'古尔，甚至追入海底深处。丹纳瓦和他的渔夫们屠戮了大部分撤退的穆\'古尔，他作为英雄返回吉尔尼斯。国王对丹纳瓦的勇敢感到感激，并授予他爵位。他被封号为"好战者"，以纪念他最初的职业-鱼贩。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50630, '"救赎者"乔舒亚大神官是曾经走过吉尔尼斯土地上最神圣的人：通过他祝福的布道，他给我们的国家带来了救赎，用神圣之光的恩宠照亮了我们的灵魂。愿我们的长兄在神圣的宁静中安息，在我们的城市陷入最黑暗的时刻时，愿他神圣的记忆为我们困扰的心灵带来安慰。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50631, '吉尔尼斯的土地上阴云密布。达瑞斯勋爵在他的庭院里召集了所有忠于他的次要贵族。吉尔尼斯城的一次访问即将到来。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50633, '"您确定吗，大人？难道哈洛家族真的是这个恶毒阴谋的幕后主使？" $B$B "毫无疑问，亲爱的卡利班。看来他们通过恶意已经开始窃取这片土地的统治权。他们一定趁着吉恩心碎的时候扭曲了他的心灵，甚至可能连他的身体也被扭曲。我们无法确定他们所声称的那种袭击国王的疾病的真正情况。" $B$B 一阵寂静，一位宛如死神本人的姐妹走进了领主的大厅。 $B$B 新的哈洛摄政领主的使者瑞甘·威洛菲尔德已经到来。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50634, '冰冷的城门向傲慢的使者敞开。他的头没有低下，他没有致以问候，他在领主的座位前冷笑着说道：“达瑞斯·雷文伍德勋爵，雷文伍德要塞和雷文希尔领地的主人。我，雷根·威洛菲尔德，来传达吉尔尼斯的新统治者的消息。”$B$B“那么我们应该如何感谢这份荣誉，无土地的领主和无荣誉的骑士？”$B$B雷根皱了皱眉，“你坐在椅子上显得多么高大，雷文伍德。然而，我带来的消息比你的傲慢和虚荣更高。”') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50635, '法庭上传来了不满的低语声。$B$B“那么，奥特兰克的污秽之辈派你前来传达什么消息，骄傲的雷根？”$B$B“我会掂量我的话，勋爵。”$B$B“如果你再对我尊主发表一次轻蔑的言论，我将用这把剑掂量你的脖子。”法庭上的一名人声言道。$B$B达瑞斯举起手示意他忠诚的朋友平静下来。$B$B“为我的人的大胆道歉。忠诚和友谊将我们紧紧相连，我相信您能理解。我渴望听到摄政王的慷慨之言。”') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50637, '在任何人发表言辞之前，洛里昂子爵跪在达瑞斯面前，递上一把满是鲜血的剑。“这把刀被他们的军队指挥官染血了。”$B$B达瑞斯盯着劳里昂：“其他人呢？”$B$B“那些投降的被带到了地窖里。其他人被铐住，被打得浑身是血。”$B$B雷根颤抖着：“我—我，勋，勋爵，这是什么意思？”') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50638, '达瑞斯从洛里昂的手中接过剑，将其指向雷根：“带走他身边的两个人和那些被铐在要塞墙上的人，将他们吊死。雷根，如果你以谦卑的态度来找我，我本可以饶你一命，可惜了。洛里昂，找一根柱子，三颗钉子和一把锤子，然后将这个传话者钉在上面。哈洛家族将感受到恐惧，甚至光明本身都会因为我的愤怒而颤抖！”') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50639, '第一次叛乱就这样开始了。达瑞斯召集了他剩下的所有士兵。 他统治下的普通民众既被他对土地的热爱所鼓舞，又对他的残暴感到恐惧。 然而，除了恐惧之外，还有尊重。 他们知道并且知道，绝望的时刻需要绝望的行动。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50640, '正义的叛军赢得了这场战斗，但代价沉重。雷文伍德要塞被摧毁，所有死在那片土地上的人再也无法分辨盟友和敌人，被奥特兰克的哈洛家族的黑暗魔法诅咒变成了复仇的怨灵。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50641, '达瑞斯与哈洛家族签署了一项条约。根据这项条约，达瑞斯将他的女儿埃莉娜嫁给哈洛家族的一名年轻领主。埃莉娜为了让达瑞斯能够购买脆弱的休战时间而牺牲了自己。$B$B但是格雷迈恩将永远坐在我们的王座上，我们将确保如此。城门将会倒下，我们会在旧有的盟约中寻求帮助。我们绝不会放弃我们的国家。$B$B用你的眼睛寻找这片土地上最高的树。这就是我们伟大人民的高度。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50642, '经过数十年的深入研究，已经不容置疑，传统上所称的鲜血魔法并非源自我们的世界。那些声称已经掌握了这种法术形式的人，本质上类似于兽人术士，他们从扭曲虚空中获得他们的能力。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50643, '耗费了许多充满挑战性的年份的任务是发现这种类型的魔法的来源。很明显，它需要以血液的形式作为燃料，并赋予咒语施法者访问外部位面的力量。然而，不清楚的是，如何建立与这个“血之维度”的联系。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50644, '起初，我深入研究了古拉巴什巨魔及其血饮者的实践，但他们的方法被证明与此不同。他们的魔法与这个“血之维度”没有关联，因为它的力量来自于他们的血神，就像大多数巨魔的魔法一样。因此，我很快放弃了这一调查线索。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50645, '一如既往，我们的高等精灵同伴证明是无价之宝。他们的古老手稿，早于传说中的“分裂时代”——如果有人愿意相信这样的传说——详细描述了他们的法术施法者从“血之维度”中汲取力量，他们的语言中称之为“沃根多尔”。文中提到的仪式似乎与我的探索相吻合。使用大量的血液可以提升施法者的体力、智力和敏捷。然而，根据手稿，这些仪式会带来许多有害的影响，包括但不限于疯狂、幻象，以及变成狼一般的生物。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50646, '随着时间的推移，他们的实验导致了灾难性的后果，他们的身体和心智被他们释放出的黑暗能量扭曲和腐化。幸存者被追捕并被驱逐出他们的家园，他们关于鲜血魔法的知识被埋藏在岁月的尘埃中。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50647, '很明显，我必须亲自进行调查。我获得所需的血液进行仪式的具体方法不必让读者关心，除了注意到这是在不伤害无辜人员的情况下完成的。<这本书现在详细描述了血魔法仪式。>') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50648, '强调这些实践应该被禁止和制止是非常必要的。我所经历的痛苦无法形容，而所获的好处微不足道，更不用说那些关于被翡翠之焰吞噬的世界的怪诞幻象。我记录下这些知识纯粹是为了警告后代不要参与这些活动，我真诚地希望克尔苏加德会永远保护这些机密。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50661, '几个世纪前，第一批牛头人部落定居在穆尔森的肥沃土地上，与我们自己的同类一样，与狂野和未驯服的自然力量和谐相处。 这些高贵的生物虽然最初未经雕琢，但与我们一样对自然抱有深深的敬畏。 我们德鲁伊的教义赋予了他们农业、畜牧业甚至文字的知识。$B$B他们的精神奉献超出了他们自己的传统，拥抱了塞纳留斯和艾露恩。 因此，联盟成立，促进共同发展和繁荣。 尽管偶尔会有误解破坏和谐，但卡多雷和牛头人和平相处。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (50662, '然而，随着半人马部族从莫雷鲁姆（现在被称为凄凉之地）的到来，历史的进程发生了致命的转变。 这些无情的军队对牛头人发起了无情的攻击，试图剥夺他们肥沃的平原，并将他们驱逐到荒凉的荒地。$B$B勇敢的牛头人在压倒性的优势下英勇作战，但战势却对他们不利。 日复一日，他们被无情地推向东方，逼近绝望的悬崖。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (80150, '\n嘿，老兄！是我，格里兹，来自地底城。还记得我吗？\n\n我写这封信是为了让你知道，我看到你向那些试图让你陷入困境的傻瓜挥舞着武器。 这让我想起了我们还是小混混时的美好时光，那一次你从那个大角魔手中救了我！\n\n多亏了你，我努力训练，成了个大人物的打手，现在我正在教其他地精如何打拳。 稍后过来，让我教你一两件事，关于如何使用你正在挥舞的那个东西。记得带上你的金币袋子哦！') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (80151, '小偷！流氓！该死的侏儒之子！\n\n别以为我没听说你在这附近潜伏，$N。你真是胆大包天，竟然敢和莱蒂·快舌一起出现。\n\n你偷走了我的买卖，这可是整个艾泽拉斯这边最大的一次劫案！我本可以暴富然后消失得无影无踪！\n\n可你却闯了进来，把一切都搞砸了。你自己都给抓住了，我敢打赌你也不是愿意为了风险公司干活的。\n\n不过没关系。到那个塌陷的洞穴来，把你欠我的钱还给我！也许你能从一个真正的潜行者身上学到一些东西。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (80152, '致$N：\n\n我是梅坦·炸炮，这里的本地猎人。信不信由你，我本来要和赫米特·奈辛瓦里一起去荆棘谷狩猎的。可惜，我欠了风险公司的债，被逼到了这个破地方。\n\n这里没什么可打的，只有秃鹫或乌鸦，但这并不意味着你不应该努力成为一名合格的神射手。我看到你之前是如何对准目标开枪的，我认为你可以从和我一起训练中受益。只需花点小钱，你就可以学会成为一名真正的射手高手。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (80153, '嘿，$N！我叫维泽特·冰哨。\n\n我听说你和我一样有聪明的头脑和魔法天赋。 有一天，你非常希望能炸掉一些东西，但你的手却着火了！ 我对吗？\n\n只要你认为足够努力，你就能做出令人惊叹的事情。 就像这整个充满笨蛋的行动一样，自发地爆发出火焰。 这坑里真是惨不忍睹啊\n\n来拜访我，让我们谈谈魔法吧！ 教你一些新咒语可能会分散我的注意力，让我不再思考这个地方着火了。\n\n哦，别忘了带一些硬币！') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (80154, '万岁，$N。我是阿姆里·恶魔交易者，黑暗艺术的超级行家。\n\n当我第一次看到你和其他废物一起苦干的时候，我感受到了与我相似的氛围。我认为你有能力召唤恶魔和施展邪能之火！\n\n我很感兴趣，希望看看你有什么本事。来我的洞穴找我吧，我们看看你是否有这个能力。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (80226, '你好，$N！\n\n我是鲁比纳·阳炎！我一直关注着你的壮举。你是一名出色的游侠，但我们失去家园的遭遇让你的训练显得不够完整。\n\n在二次战争期间，法斯特赛德人在小屋外种下了一颗来自我们家园的种子。如今，那棵树已不仅仅是一个提醒，它代表了我们将来夺回家园的希望。\n\n作为游侠，我们的任务是无论在哪里都要保卫我们的人民。\n\n我可以继续你的训练。当你准备好的时候，请来小屋找我谈谈。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (80227, '$N，我是洛萨斯·圣光之子。曾经我是白银之手骑士团的一员。\n\n在白银之手骑士团和洛丹伦王国的覆灭之前，我是一名圣骑士，是光明的勇敢仆人，无论黑暗在何处，我都会将其驱散。你的道路与我的相似。你怀揣光明的意志，同时拥有强大的战斗能力。\n\n请在小屋里找到我，我会尽我所能地训练你。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (80228, '愿光明与你同在，$N。\n\n我是梅拉·阳誓。\n\n我曾在奎尔萨拉斯的神殿中受命，在那里我学会了传扬太阳之光。我曾在同一间里面与高阶祭司贝洛维尔一同徜徉。\n\n可惜那些日子早已过去，我们的神殿遭受毁灭，太阳的温暖也被抛弃。\n\n我已经看到了你内心虔诚和信仰的火花。\n\n请到小屋里与我交谈。我将很愿意引导你的道路，以便有一天，我们的人民不仅能恢复对光明的信仰，还能重新寄望于我们的未来。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (80229, '你好吗， $N. 你有幸得到太阳之血家族的魔导师阿拉绍尔称呼。\n\n我看到你对魔法的了解超过了普通难民。然而如今的魔导学会已经不再是曾经的辉煌。作为奎尔萨拉斯的魔导师，我不能任由这种情况继续下去。\n\n无论我们的家园发生了什么，我自己的职责或魔导学会的职责从未停止过。\n\n来找我，我将让你成为我的学徒。如果你能承受得住我的训练，你将成为一位出色的魔法施法者。配得上重建的主教座堂。。\n\n请在小屋里寻找我。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (80230, '嘿，$N。 我写信给你是因为你看起来是一个有用的资产。\n\n这里的每个人都会很高兴地夸耀荣誉、正直、太阳或其他类似的废话，但我不会。 我知道，为了保证我们人民的安全，必须使用更严厉的方法。\n\n我们的人民需要有人躲在阴影中、了解情况、报告情况，甚至提前结束威胁。 我感觉到你内心对我希望建立的那种秩序有一种亲和力。\n\n来找我吧，我会让你的时间变得值得。 我会在旅馆等你。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (80231, '向你致敬，$N！\n\n我是瓦拉诺斯·黎明火，萨拉斯军队的剑士。\n\n随着奎尔萨拉斯的陷落，我现在的职责是保护我们剩下的土地、我们的遗产和我们的人民，无论他们居住在哪里。\n\n这项职责包括培训能够捍卫我们事业的新战士。\n\n来小屋里找我吧，$N，我会把你缺乏经验的身体磨练成一名战士，一个可以保护高等精灵的战士！') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (80300, '这是来自艾萨拉的加兹托格的报告！\n\n我在工作中遭受了很多挫折，我分配给我的助手弗里克斯几乎把我交给他的每项任务都搞砸了，还差点把我们分配的测量装备弄丢了。\n\n弗里克斯被当地的萨特杀死了，测量装置也从他们手中夺了回来，我需要尽快找一个新的助手，而且是一个值得我花时间的助手！') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (80301, '使用魔网碎片进行的测试完全没有价值，位于埃达拉斯废墟周围的碎片不稳定，在使用时会发出嗤嗤声。\n\n使用虚灵精华进行的测试也被证明效果平平。\n\n虽然它们保存了能量，但这种能量非常微弱，就像侏儒的风格一样。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (80305, '你好兄弟，\n\n我希望这封信能让你一切顺利，我在火花港的地精那里做得不错，我知道你说我的冒险是愚蠢的，但是这份工作带来了很多钱！') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (80306, '杜隆塔尔的天气仍然像往常一样炎热，阳光炽烈。\n\n我很高兴听到你的成功，祝愿你好运。\n\n希望很快能从你那里听到消息，让我们保持联系。\n\n鲁格纳。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (80308, '鲁格纳，在悲伤沼泽杂草丛生的地方读到你的话很舒服。\n\n我已经请假了，很快就要启程前往奥格瑞玛了，我们已经很久没有见面了，我对此非常期待，并且有很多事情要告诉你。\n\n你的兄弟祖尔') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (80309, '在我参与的所有项目中，唯一取得成功的是来自当地“雷云部落”的“飞天角”项目。它们的能量爆棚，绝对值得在“闪耀之水”上尝试。我会尽快发送一些测试样本！\n\n报告人，加兹托格尔。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (80310, '根据预言，众神将抛弃不忠者，并分裂那些不听劝告者。\n\n世界将发生变化，灵魂将受到污染，最终破碎。\n\n岩石将凋零，风将消失，水将干涸，要注意末日的警告，因为正是元素自身需要我们的帮助。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (80311, '老板，非常抱歉送货晚了，以后不会再晚，我向您保证！我在里面附上了一些额外的钱，作为时间上的补偿。\n\n塔罗。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (80320, '致雪须船长，\n\n铁炉堡与米奈希尔港之间的补给线每天都受到压力。商队遭到龙喉兽人的袭击，甚至抵达您那里都变成了一项危险的挑战。\n\n需要更多的帮助，以及解决威胁我们土地的龙喉问题所需的支援。如果您有多余的士兵，现在正是借出他们的时候。\n\n斯托特菲斯特船长。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (80322, '斯托特菲斯特船长，很抱歉我无法提供帮助。 尽管龙喉对我们双方都构成了威胁，但我在山区的人手严重不足，无法继续进攻，而且无法借出我的一些登山者来帮助你们。\n\n我祝愿你在这件事上一切顺利，并以麦格尼的胡须祈祷铁炉堡能为我们俩带来帮助。\n\n  铁炉堡军队的雪须船长') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (80324, '嘿，是我，巴托斯，我需要以下材料来制作两个倾斜振荡抑制器：\n\n16块铁锭\n6份强效助熔剂\n2个青铜嗡嗡装置\n2捆熔化的导线') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (80325, '这就是所需的全部材料！\n\n祝你在寻找过程中好运，而且要快点。任务繁重！\n\n鹰眼哨站的工程传奇，巴索斯·雷霹。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (80326, '巴索斯，如果议会发现所有这些供应品都被运到了鹰眼哨站，他们会非常愤怒的。毕竟，机场的开支相当大！确保我送给你的这些供应品在尽可能长的时间内足够使用，然后再考虑是否需要更多。\n\n你的朋友，奥里恩·煤胎。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (80327, '致拉蒙三世公爵，\n\n再次感谢您所做的一切。为了我的安全，自从我离开暴风城以来，我不得不保持低调。\n\n似乎军情七处一直在监视着我，但我向您保证，到目前为止我一直保持不被察觉，并且很好地藏匿在我的房间里。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (80328, '您的支持至关重要，使我摆脱了那个悲惨的寨子。\n\n我的叔叔会为能称您为一位伟大的朋友而感到自豪，我希望很快能从您那里听到消息，我不确定我何时会离开这个地方。\n\n一位朋友，马丁·科林斯。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (80329, '亲爱的指挥官莱克大人，\n\n我已委托此信封的持有者将此信息交付。\n\n您正在调查的人，哈勒斯·艾什巴克尔，是使用假名行事的，他的真名是马丁·科林斯，他来自洛丹伦，于第三次战争爆发时逃脱。\n\n马丁来自一个富有的家庭，并与暴风城的贵族有许多联系。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (80330, '正是这样的联系使马丁免于因谋杀无辜和使用禁忌魔法而在暴风城被处决。\n\n如果有一种邪恶的魔法困扰着鹰眼哨站的守夜者，我会怀疑他对此负有责任。\n\n马丁·科林斯在被从暴风城放逐（这是他出狱的“条件”）后，将放弃联盟所掌握的所有领域内的黑暗魔法。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (80331, '我将赋予您暴风城的裁决权，以向这个人施以公正的制裁，这是早就应该做的事情。\n\n让您的领土远离他可能带来的一切黑暗。\n\n大师马修斯·肖，军情七处领袖。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (1000243, '十字军对抗天灾之墙\n\n血色十字军的圣骑士，银色之手的骑士，在对抗敌人的战争中光荣地服役。\n\n从未有人像您一样无所畏惧，坚守职责，您的品德是所有十字军所仰望的灵感之源，您的判断将永远被铭记。\n\n您曾是我们同胞的拳头，那道阻止邪恶前行的墙。\n\n愿圣光引领您以与生前同样的热情踏上新的征程。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (1000244, '入会者的誓言\n\n我将为十字军东征服务，并保证我的生命为其事业，我将毫无疑问地服从，我将响应我人民的号召。\n\n十字军的誓言\n\n捍卫我人民的土地是我的信条，因为洛丹伦即是十字军，而十字军即是洛丹伦。我将对所有冒犯我战友的人施以公正。我是曾经存在的化身。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (1000245, '骑士的誓言\n\n我将维护高贵之物。\n我将毁灭腐化之物。\n我将保护神圣之物。\n\n对于我的兄弟姐妹，此誓言永真。\n\n传教士的誓言\n\n对于我种族的传承，是我责无旁贷的使命，保护圣教的方式和传统，并在这场神圣的战争中神圣化和祝福我们的武器。清除欺骗者、异端和不忠者，是我的使命。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (1000246, '光明，在这些破败和受瘟疫蹂躏的土地中，它是我们的守护者，曾经充满生机和美丽的土地现在已经变成了腐朽。我们是黑暗中的火炬，而光明是阻止黑暗的力量。它是曾经和未来洛丹伦的光辉典范，我们将在其道路上创造。圣骑士和我们教团的牧师们用它的伟大带来了毁灭性的影响，正如许多兄弟姐妹所看到的那样。\n\n我们应该将希望、祈祷和信任寄托在圣光之中。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (1000247, '作为这个秩序的创立者，它是我们的信标，现在仍然将我们紧密相连，尽管经历了如此多的困难和考验。尽管我们多次陷入毁灭的边缘，尽管我们周围的王国已经倒塌，我们仍然坚定不移地站立。\n\n如果黑暗逼近的时刻到来，') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (1000248, '请记住，圣光始终闪耀在你身上，你的牺牲将在圣光的恩典中得到充分的回报。\n\n圣光不会放弃，圣光不会忘记。 让我们永远把它记在心里。\n\n无论世界多么黑暗，光明总会再次闪耀。\n\n~抄写员达福德') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
INSERT INTO `locales_page_text` (`entry`, `Text_loc4`) VALUES (1772030, '格瑞姆巴托纪念碑\n\n一个神龛，献给那些在保护无辜者免受我们最大的挑战时英勇战斗并献出生命的人们。愿这座神龛永远纪念那些在我们曾经伟大的大厅内，以抵抗侵略者的姿态而去世的人们。\n\n你们永远不会被遗忘。') ON DUPLICATE KEY UPDATE `Text_loc4` = VALUES(`Text_loc4`);  -- 
